# -*- coding: utf-8 -*-
"""T6 — Descrições da Pokédex (espécies 387-1025, Gen 4-9) em PT-BR.

Formato: var -> lista de linhas (<=42 chars cada, até 4 linhas), aplicado
em src/data/pokemon/pokedex_text_gen4_9.h por aplicar_traducao.py.
Os textos originais vinham truncados do PokeAPI; aqui foram reescritos
por completo dentro do limite da caixa.
"""

TRADUCOES = {
    "sPokedexText_TURTWIG": ["O casco de suas costas é feito de solo.", "Num Turtwig bem saudável, o casco é", "úmido ao toque. A folha da cabeça", "murcha se ele tem sede."],
    "sPokedexText_GROTLE": ["Dizem que um Grotle que vive na", "floresta tem seu próprio poço secreto", "de água de nascente."],
    "sPokedexText_TORTERRA": ["Alguns Pokemon nascem nas costas de um", "Torterra e passam a vida toda ali.", "Povos antigos criam que havia um", "Torterra sob a terra."],
    "sPokedexText_CHIMCHAR": ["Seu traseiro em chamas é movido a gás", "produzido na barriga. Antes de dormir,", "Chimchar apaga a chama para", "não causar incêndios."],
    "sPokedexText_MONFERNO": ["Controla com cuidado a intensidade da", "chama de sua cauda para manter os", "rivais a uma distância adequada."],
    "sPokedexText_INFERNAPE": ["Sua coroa de fogo mostra sua natureza", "ardente. Usa um tipo especial de arte", "marcial que envolve todos os", "seus membros."],
    "sPokedexText_PIPLUP": ["Anda mal e cai com frequência. Porém,", "seu orgulho forte o faz estufar o", "peito sem se abalar."],
    "sPokedexText_PRINPLUP": ["Como cada Prinplup se considera o mais", "importante de todos, eles nunca", "conseguem formar bandos."],
    "sPokedexText_EMPOLEON": ["Os três chifres do bico atestam seu", "poder. Evita disputas desnecessárias,", "mas dizima quem fere seu orgulho."],
    "sPokedexText_STARLY": ["Reúnem-se em bandos por montes e", "campos, caçando Pokemon insetos.", "Porém, brigam se o grupo", "cresce demais."],
    "sPokedexText_STARAVIA": ["Cientes da própria fraqueza, mantêm", "bandos enormes. Brigas ferozes estouram", "entre os bandos. Sozinho,", "um Staravia grita sem parar."],
    "sPokedexText_STARAPTOR": ["Ao evoluir para Staraptor, deixam o", "bando para viver sós. Tem natureza", "feroz e enfrenta com coragem até", "inimigos bem maiores."],
    "sPokedexText_BIDOOF": ["Uma comparação revelou que os dentes", "frontais de Bidoof crescem na mesma", "velocidade que os de Rattata."],
    "sPokedexText_BIBAREL": ["Faz o ninho represando riachos com", "casca e lama. Um rio represado por", "Bibarel nunca transborda, o que o", "povo da região agradece."],
    "sPokedexText_KRICKETOT": ["Balança a cabeça para trás e para", "frente, fazendo as antenas baterem uma", "na outra como um xilofone. Esses sons", "são a marca do outono."],
    "sPokedexText_KRICKETUNE": ["Sinaliza suas emoções com melodias.", "Há um vilarejo que realiza um concurso", "para imitar seu som."],
    "sPokedexText_SHINX": ["Contrai e relaxa os músculos bem", "rápido para gerar eletricidade. Seu", "corpo brilha em perigo, e ele foge", "enquanto o rival está cego."],
    "sPokedexText_LUXIO": ["Eletricidade forte corre pelas pontas", "de suas garras afiadas. Um arranhão de", "leve já tem amperagem para", "causar desmaio."],
    "sPokedexText_LUXRAY": ["Tem olhos que enxergam através de", "qualquer coisa. Essa visão de Luxray é", "bem útil quando ele vigia", "procurando perigos."],
    "sPokedexText_BUDEW": ["No inverno, fecha o botão e aguenta o", "frio. Sensível à mudança de", "temperatura, dizem que o botão", "floresce na primavera."],
    "sPokedexText_ROSERADE": ["Seu doce aroma atrai presas. Com", "movimentos de dançarino, golpeia com", "chicotes cobertos de", "espinhos venenosos."],
    "sPokedexText_CRANIDOS": ["Morador das selvas de 100 milhões de", "anos atrás, seu crânio é duro", "como ferro."],
    "sPokedexText_RAMPARDOS": ["O resultado de tantas cabeçadas é um", "crânio grosso e rijo. Porém, seu", "cérebro encolheu em comparação", "com o de Cranidos."],
    "sPokedexText_SHIELDON": ["Este Pokemon vivia em selvas", "primitivas. Poucos inimigos ousavam", "encarar seu rosto tão", "bem blindado."],
    "sPokedexText_BASTIODON": ["Seus rostos duros como rocha os", "protegem de qualquer ataque frontal.", "Quando atacados, formam um muro para", "proteger os filhotes."],
    "sPokedexText_BURMY": ["Se sua capa sofre o menor dano, ele a", "repara de imediato com o material que", "tiver por perto."],
    "sPokedexText_WORMADAM": ["Sua aparência muda conforme o lugar", "onde Burmy evoluiu. Os materiais ao", "redor viram parte do corpo.", "A capa nunca é trocada."],
    "sPokedexText_MOTHIM": ["Mothim vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_COMBEE": ["Um Pokemon formado por três outros.", "Colhe mel das flores sem parar para", "agradar Vespiquen. À noite, dormem", "empilhados às centenas."],
    "sPokedexText_VESPIQUEN": ["Abriga sua colônia nas células do", "corpo e libera vários feromônios para", "fazer as larvas obedecerem", "às suas ordens."],
    "sPokedexText_PACHIRISU": ["Um casal pode ser visto esfregando as", "bolsas das bochechas para dividir a", "eletricidade guardada. Ele a armazena", "junto com as frutas."],
    "sPokedexText_BUIZEL": ["Infla sua boia natural para manter o", "rosto fora da água e vigiar o", "movimento das presas. Nada girando", "as duas caudas como hélice."],
    "sPokedexText_FLOATZEL": ["Sua boia natural se desenvolveu da", "caça a presas aquáticas. Ele pode", "inflá-la e desinflá-la à vontade."],
    "sPokedexText_CHERUBI": ["A bolinha guarda os nutrientes", "necessários à evolução. Pelo visto,", "ela também é bem doce e saborosa."],
    "sPokedexText_CHERRIM": ["Fica imóvel, salvo um tremor de vez em", "quando. Muitos Pokemon se reúnem ao", "seu redor, atraídos pelo doce", "aroma de suas folhas."],
    "sPokedexText_SHELLOS": ["Consegue passar um tempo limitado em", "terra, até sua pele secar.", "Sua forma varia conforme", "o ambiente."],
    "sPokedexText_GASTRODON": ["Mais visto em terra do que no mar.", "Costuma viver em costas rochosas, mas", "busca comida também na lama", "de águas rasas."],
    "sPokedexText_AMBIPOM": ["Vivem em árvores grandes. Divididas em", "duas, suas caudas são tão hábeis que", "Ambipom quase não usa os braços."],
    "sPokedexText_DRIFLOON": ["Pelo seu jeito de flutuar sem rumo, um", "velho conto popular o chama de", "“Guia dos Perdidos”."],
    "sPokedexText_DRIFBLIM": ["Mesmo sob observação cuidadosa,", "grandes bandos de Drifblim voando ao", "anoitecer somem de vista sem", "qualquer explicação."],
    "sPokedexText_BUNEARY": ["Dá para saber como se sente pelo jeito", "que enrola as orelhas. Com medo, as", "duas ficam enroladas; alerta,", "elas se levantam."],
    "sPokedexText_LOPUNNY": ["Um Pokemon extremamente cauteloso.", "Preocupa-se muito com a aparência e", "nunca deixa de limpar as orelhas.", "Corre com saltos vivazes."],
    "sPokedexText_MISMAGIUS": ["Seus gritos soam como encantamentos.", "Quem os ouve sofre com dores de cabeça", "e alucinações. Aparece onde", "menos se espera."],
    "sPokedexText_HONCHKROW": ["Ativo à noite, é famoso por andar com", "um bando de Murkrow a reboque. Dizem", "que nunca perdoa os erros", "de seus capangas."],
    "sPokedexText_GLAMEOW": ["Um Pokemon bem volúvel, muito popular", "entre alguns. Arranha o nariz do", "Treinador se não é alimentado e", "ronrona quando carinhoso."],
    "sPokedexText_PURUGLY": ["Um brutamontes atrevido que invade o", "ninho de outro Pokemon e o toma para", "si. Enrola a cauda dupla na cintura", "para parecer maior."],
    "sPokedexText_CHINGLING": ["Há uma esfera dentro de sua boca.", "Quando pula, a esfera quica por todo", "lado e tilinta. Consegue gritar por", "um tempão sem parar."],
    "sPokedexText_STUNKY": ["Protege-se borrifando do traseiro um", "fluido de cheiro insuportável para", "repelir agressores. O fedor", "dura 24 horas."],
    "sPokedexText_SKUNTANK": ["Ataca borrifando um fluido de odor", "horrível da ponta da cauda. O fluido", "alcança mais de 50 metros", "de distância."],
    "sPokedexText_BRONZOR": ["Objetos com seu formato foram achados", "em tumbas antigas. Há pesquisadores", "que creem que este Pokemon era", "reverenciado no passado."],
    "sPokedexText_BRONZONG": ["Em eras passadas, este Pokemon era", "venerado como trazedor de chuvas. Um", "deles causou alvoroço ao despertar", "numa escavação."],
    "sPokedexText_BONSLY": ["Bonsly prefere ambientes áridos. Para", "ajustar o nível de fluidos do corpo,", "verte água pelos olhos, parecendo", "estar chorando."],
    "sPokedexText_MIME_JR": ["Para confundir o inimigo, imita os", "movimentos dele. Uma vez imitado, o", "rival não consegue tirar os olhos", "deste Pokemon."],
    "sPokedexText_HAPPINY": ["Carrega uma pedra branca e redonda na", "bolsa da barriga. Se simpatiza com", "alguém, às vezes presenteia", "a pessoa com a pedra."],
    "sPokedexText_CHATOT": ["Imita os gritos de outros Pokemon para", "enganá-los e se passar por um deles.", "Repete o que ouve humanos falarem."],
    "sPokedexText_SPIRITOMB": ["Um Pokemon formado por 108 espíritos.", "Suas travessuras e malfeitos", "constantes o deixaram preso a uma", "pedra-chave mística."],
    "sPokedexText_GIBLE": ["Aninha-se em tocas horizontais", "aquecidas pelo calor geotérmico. Quem", "chega perto demais pode esperar um", "bote e uma mordida."],
    "sPokedexText_GABITE": ["Objetos brilhantes são sua paixão.", "Fica em sua caverna, quase sem se", "mover, com o olhar fixo nas joias", "que acumulou."],
    "sPokedexText_GARCHOMP": ["Quando encolhe o corpo e estende as", "asas, parece um avião a jato.", "Voa na velocidade do som."],
    "sPokedexText_MUNCHLAX": ["Quando encontra algo com cara de", "comestível, engole de uma vez.", "Por isso, vive com dor", "de barriga."],
    "sPokedexText_RIOLU": ["Percebe o estado físico e emocional de", "pessoas, Pokemon e outros seres pela", "forma de suas auras."],
    "sPokedexText_LUCARIO": ["Entende a fala humana. Dizem que rival", "algum consegue ficar invisível para", "Lucario, pois ele detecta Auras."],
    "sPokedexText_HIPPOPOTAS": ["Hippopotas fecha bem as narinas ao", "viajar pela areia. Em vez de suor,", "expele grãos de areia pelo corpo."],
    "sPokedexText_HIPPOWDON": ["Irrita-se com surpreendente rapidez.", "Escancara a boca enorme numa exibição", "de força temível e ergue nuvens", "de areia ao atacar."],
    "sPokedexText_SKORUPI": ["Agarra a presa com as garras da cauda", "e injeta veneno, segurando firme até o", "veneno agir. Sobrevive um", "ano sem comer."],
    "sPokedexText_DRAPION": ["De constituição robusta, orgulha-se da", "própria força. Seus braços com garras", "têm poder para fazer picadinho", "de um carro."],
    "sPokedexText_CROAGUNK": ["Croagunk raramente luta limpo.", "Inflando as bolsas de veneno, enche a", "área com um som sinistro e golpeia", "o rival distraído."],
    "sPokedexText_TOXICROAK": ["Gingando e desviando dos ataques dos", "rivais, aproxima o corpo flexível e", "então desfere o bote com seus", "dedos venenosos."],
    "sPokedexText_CARNIVINE": ["Pendurado nos galhos pelos tentáculos,", "parece uma planta. Atrai a presa com", "saliva de cheiro doce e a devora."],
    "sPokedexText_FINNEON": ["Suas duas nadadeiras caudais propelem", "saltos cheios de energia. Ao romper a", "superfície da água à noite, suas", "caudas gêmeas cintilam."],
    "sPokedexText_LUMINEON": ["Lumineon nadando na escuridão do mar", "profundo parecem estrelas brilhando no", "céu noturno. Disputa comida", "com Lanturn."],
    "sPokedexText_MANTYKE": ["Quando nada perto da superfície do", "oceano, as pessoas a bordo de navios", "conseguem observar o padrão", "de suas costas."],
    "sPokedexText_SNOVER": ["Nas estações frias, migra para as", "partes baixas da montanha. Parecendo", "curiosos sobre pessoas, reúnem-se", "em volta de pegadas."],
    "sPokedexText_ABOMASNOW": ["Vive em paz nas montanhas de neves", "eternas. Esconde-se levantando", "nevascas e some como o", "abominável homem das neves."],
    "sPokedexText_WEAVILE": ["Viajam em grupos de quatro ou cinco,", "deixando sinais uns aos outros em", "árvores e pedras. Abatem a presa", "com ataques coordenados."],
    "sPokedexText_MAGNEZONE": ["Ao cruzar os céus, este Pokemon parece", "receber sinais de origem desconhecida,", "enquanto transmite sinais de", "propósito ignorado."],
    "sPokedexText_LICKILICKY": ["A longa língua vive encharcada de", "baba. A saliva contém um solvente que", "causa dormência. Chegar perto demais", "é pedir uma lambida."],
    "sPokedexText_RHYPERIOR": ["Lança uma rocha segurada na mão como", "um míssil, contraindo e expandindo os", "músculos num instante. Às vezes,", "dispara Geodude."],
    "sPokedexText_TANGROWTH": ["Enlaça a presa estendendo braços", "feitos de vinhas. Mesmo que um braço", "seja comido, não sente dor e", "cresce outro logo."],
    "sPokedexText_ELECTIVIRE": ["Quando se empolga, bate no peito.", "A cada baque, o trovão ruge e faíscas", "elétricas choviscam ao redor."],
    "sPokedexText_MAGMORTAR": ["Pelo que se sabe, um único casal de", "Magmortar vive em cada vulcão. Do", "braço, lança bolas de fogo de", "mais de 2.000 graus."],
    "sPokedexText_TOGEKISS": ["Como todos sabem, visita regiões", "pacíficas trazendo presentes de bondade", "e doces bênçãos. Nunca aparece", "onde há conflito."],
    "sPokedexText_YANMEGA": ["Este Pokemon de seis patas carrega com", "facilidade um adulto em pleno voo.", "Sabe muito bem onde ficam os pontos", "fracos da presa."],
    "sPokedexText_LEAFEON": ["Sua composição celular é mais próxima", "da de uma planta que de um animal. Usa", "fotossíntese para produzir", "sua energia."],
    "sPokedexText_GLACEON": ["Controla a temperatura do corpo à", "vontade. Assim, congela a umidade da", "atmosfera, criando flocos de", "poeira de diamante."],
    "sPokedexText_GLISCOR": ["Gliscor observa a presa pendurado de", "cabeça para baixo nos galhos. Seu voo", "é silencioso. Na hora certa,", "ataca num mergulho."],
    "sPokedexText_MAMOSWINE": ["Um Mamoswine congelado foi escavado de", "gelo de 10.000 anos. Ele acordou,", "para espanto geral. Este Pokemon", "existe desde essa era."],
    "sPokedexText_PORYGON_Z": ["Para criar um Pokemon mais avançado,", "um programa adicional foi instalado,", "mas ao que parece ele", "continha um erro."],
    "sPokedexText_GALLADE": ["Mestre da cortesia e da esgrima, luta", "usando espadas extensíveis nos", "cotovelos."],
    "sPokedexText_PROBOPASS": ["Controla livremente três unidades", "chamadas Mini-Narizes usando força", "magnética. Com elas, ataca os rivais", "de três direções."],
    "sPokedexText_DUSKNOIR": ["Dizem que este temido Pokemon viaja a", "mundos desconhecidos. Alguns creem até", "que leva espíritos perdidos em", "seu corpo maleável."],
    "sPokedexText_FROSLASS": ["Ao achar pessoas ou Pokemon de que", "gosta, congela-os e os leva para sua", "toca gelada, onde viram", "sua decoração."],
    "sPokedexText_ROTOM": ["Seu corpo é feito de plasma e adora", "surpreender os outros. A invenção de", "um garoto levou-o a entrar", "em aparelhos."],
    "sPokedexText_UXIE": ["Conhecido como “O Ser do", "Conhecimento”. Segundo algumas fontes,", "este Pokemon deu às pessoas a", "inteligência para viver."],
    "sPokedexText_MESPRIT": ["Embora durma no fundo de um lago,", "dizem que seu espírito deixa o corpo", "para voar sobre a água."],
    "sPokedexText_AZELF": ["Dizem que este Pokemon deu aos humanos", "a determinação para agir. Crê-se que", "Uxie, Mesprit e Azelf vieram", "de um mesmo ovo."],
    "sPokedexText_DIALGA": ["Um Pokemon das lendas. Controla por", "completo o fluxo do tempo. Usa esse", "poder para viajar à vontade", "pelo passado e futuro."],
    "sPokedexText_PALKIA": ["Palkia tem a habilidade de distorcer o", "espaço. Seu controle total sobre as", "fronteiras do espaço rendeu", "menções em mitos."],
    "sPokedexText_HEATRAN": ["Sangue fervente, como magma, circula", "em seu corpo. Vive em cavernas", "vulcânicas, usando os pés em cruz", "para escalar paredes."],
    "sPokedexText_REGIGIGAS": ["Há uma lenda duradoura de que este", "Pokemon moldou Regirock, Regice e", "Registeel a partir de argila,", "gelo e magma."],
    "sPokedexText_GIRATINA": ["Giratina perde as pernas ao mudar para", "esta forma. Crê-se que vem de um mundo", "oposto ao nosso."],
    "sPokedexText_CRESSELIA": ["Quem dorme segurando uma pena de", "Cresselia tem sonhos felizes", "garantidos. Dizem que representa a", "lua crescente."],
    "sPokedexText_PHIONE": ["Quando a água esquenta, inflam a boia", "da cabeça e flutuam preguiçosos pelo", "mar em cardumes. Sempre volta para", "onde nasceu."],
    "sPokedexText_MANAPHY": ["Água compõe 80% do seu corpo. Nasce", "com um poder maravilhoso que permite", "criar laços com qualquer", "tipo de Pokemon."],
    "sPokedexText_DARKRAI": ["Expulsa pessoas e Pokemon do seu", "território fazendo-os cair em sonos", "profundos e cheios de pesadelos. Mas", "não faz por maldade."],
    "sPokedexText_SHAYMIN": ["Ao sentir o aroma de certa flor rara,", "Shaymin é envolto em luz e muda", "para sua Forma Céu."],
    "sPokedexText_ARCEUS": ["Arceus vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_VICTINI": ["Este Pokemon traz vitória. Dizem que", "Treinadores com Victini sempre vencem,", "não importa o tipo de disputa."],
    "sPokedexText_SNIVY": ["É muito inteligente e calmo. Tomar", "bastante sol deixa seus movimentos", "mais rápidos. Indisposto, sua", "cauda murcha."],
    "sPokedexText_SERVINE": ["Quando se sujam, suas folhas não", "servem para a fotossíntese, então ele", "sempre se mantém limpo."],
    "sPokedexText_SERPERIOR": ["Erguem a cabeça para intimidar rivais,", "mas só dão tudo de si ao enfrentar", "oponentes à altura."],
    "sPokedexText_TEPIG": ["Adora comer BERRIES assadas, mas às", "vezes se empolga e as torra demais.", "Sopra fogo pelo focinho."],
    "sPokedexText_PIGNITE": ["Quanto mais come, mais combustível tem", "para fortalecer o fogo no estômago.", "Quando se zanga, a intensidade das", "chamas aumenta."],
    "sPokedexText_EMBOAR": ["É hábil com muitos golpes diferentes.", "Consegue dar um soco de fogo acendendo", "os punhos com a barba", "em chamas."],
    "sPokedexText_OSHAWOTT": ["A concha da barriga não serve só para", "lutar: também quebra BERRIES duras.", "É feita do mesmo material", "que as garras."],
    "sPokedexText_DEWOTT": ["Treino e disciplina rigorosos o levam", "a dominar sua fluida técnica de duas", "conchas. As técnicas variam de", "um Dewott para outro."],
    "sPokedexText_SAMUROTT": ["Um só golpe das espadas presas à", "armadura derruba um oponente. Um mero", "olhar de um deles já intimida a", "maioria dos inimigos."],
    "sPokedexText_PATRAT": ["Extremamente cautelosos, fazem turnos", "para manter vigília constante do", "ninho. Guardam comida nas bolsas", "das bochechas."],
    "sPokedexText_WATCHOG": ["Com matéria luminescente, faz os olhos", "e o corpo brilharem e atordoa os", "agressores. A visão aguçada", "enxerga no escuro."],
    "sPokedexText_LILLIPUP": ["Enfrenta oponentes fortes com grande", "coragem. Como não gane, é muito", "popular entre Treinadores que moram", "em apartamentos."],
    "sPokedexText_HERDIER": ["Seu denso pelo preto cresce sem parar.", "O alto custo de manter o pelo rijo bem", "aparado faz dele um Pokemon", "para poucos."],
    "sPokedexText_STOUTLAND": ["Inteligente, bondoso e valente, jamais", "haveria receio de que atacasse uma", "pessoa. É ótimo em resgates", "no mar e na montanha."],
    "sPokedexText_PURRLOIN": ["Seu numerzinho fofo é o disfarce", "perfeito. Roubam das pessoas por", "diversão, mas as vítimas acabam", "perdoando sua carinha."],
    "sPokedexText_LIEPARD": ["Muitos Treinadores se encantam com sua", "forma e pelagem belas. Estes Pokemon", "somem e aparecem sem aviso. Correm em", "silêncio pela noite."],
    "sPokedexText_PANSAGE": ["Este Pokemon vive no fundo da", "floresta. É bom em achar BERRIES e as", "reparte com os companheiros."],
    "sPokedexText_SIMISAGE": ["De gênio ruim, ataca os inimigos", "girando sua cauda espinhosa sem", "controle. A folha da cabeça", "é muito amarga."],
    "sPokedexText_PANSEAR": ["O fogo no tufo da cabeça chega a 300", "graus. Muito inteligente, assa BERRIES", "antes de comê-las."],
    "sPokedexText_SIMISEAR": ["Adora doces, pois eles viram energia", "para o fogo que arde em seu corpo.", "Espalha brasas da cabeça e da cauda", "para chamuscar rivais."],
    "sPokedexText_PANPOUR": ["A água guardada no tufo da cabeça é", "rica em nutrientes. Rega plantas com a", "cauda, e elas crescem grandes", "e viçosas."],
    "sPokedexText_SIMIPOUR": ["Atira pela cauda água sob alta pressão", "com força para romper uma parede de", "concreto. Prefere lugares de", "água limpa."],
    "sPokedexText_MUNNA": ["Este Pokemon aparece diante de pessoas", "e Pokemon que têm pesadelos e come", "esses sonhos. Munna sempre", "flutua no ar."],
    "sPokedexText_MUSHARNA": ["A névoa que emana de sua testa é", "repleta dos sonhos de pessoas e", "Pokemon. Essa névoa pode tomar", "a cor dos sonhos."],
    "sPokedexText_PIDOVE": ["Este Pokemon bem esquecido fica", "esperando a nova ordem do Treinador,", "mesmo que a anterior ainda não", "tenha sido cumprida."],
    "sPokedexText_TRANQUILL": ["Não importa aonde vá no mundo, sabe", "onde fica o ninho, e assim sempre", "retorna até o Treinador,", "onde ele estiver."],
    "sPokedexText_UNFEZANT": ["Os machos têm plumagem na cabeça.", "As fêmeas voam melhor que os machos.", "Só se afeiçoam de verdade ao", "próprio Treinador."],
    "sPokedexText_BLITZLE": ["Sua crina brilha quando descarrega", "eletricidade. Usam a frequência e o", "ritmo desses clarões para se", "comunicar entre si."],
    "sPokedexText_ZEBSTRIKA": ["Quando Zebstrika corre a toda, o som", "de trovões ecoa. Zangado, é perigoso:", "dispara raios da crina em", "todas as direções."],
    "sPokedexText_ROGGENROLA": ["A cavidade hexagonal é sua orelha.", "Caminha na direção dos sons que ouve,", "mas, se eles cessam, entra em pânico", "e tomba na hora."],
    "sPokedexText_BOLDORE": ["Seu cristal laranja é uma massa de", "energia. Um só fragmento do cristal", "daria energia a uma casa", "por 100 anos."],
    "sPokedexText_GIGALITH": ["As rajadas de energia que produz com a", "luz do sol têm poder aterrador. Porém,", "não consegue dispará-las", "à noite."],
    "sPokedexText_WOOBAT": ["Vive em florestas escuras e cavernas.", "A sucção das narinas o prende às", "paredes da caverna no sono. Deixa", "uma marca de coração."],
    "sPokedexText_SWOOBAT": ["Quem entra em contato com as ondas", "ultrassônicas emitidas por um macho em", "cortejo sente o humor melhorar", "na mesma hora."],
    "sPokedexText_DRILBUR": ["Cava o solo a 50 km/h girando o", "próprio corpo. Em disparada, daria", "trabalho até para um carro", "na superfície."],
    "sPokedexText_EXCADRILL": ["A mais de 90 metros de profundidade,", "constroem ninhos em labirinto. Sua", "atividade pode danificar túneis", "de metrô."],
    "sPokedexText_AUDINO": ["Sua audição é impressionante. Com as", "antenas das orelhas, percebe como", "alguém se sente ou quando um ovo", "está para chocar."],
    "sPokedexText_TIMBURR": ["Estes Pokemon aparecem em obras e", "ajudam na construção. Sempre carregam", "vigas de madeira. Conforme crescem,", "carregam vigas maiores."],
    "sPokedexText_GURDURR": ["Fortalecem o corpo carregando vigas de", "aço. Este Pokemon é tão musculoso que", "nem um time de lutadores", "o faria sair do lugar."],
    "sPokedexText_CONKELDURR": ["Usam pilares de concreto como", "bengalas. Em vez de confiar só na", "força, dominam golpes que usam o peso", "e o giro dos pilares."],
    "sPokedexText_TYMPOLE": ["Vibrando as bochechas, emite ondas", "sonoras imperceptíveis aos humanos.", "Usa o ritmo desses sons para falar", "com os companheiros."],
    "sPokedexText_PALPITOAD": ["Vive na água e em terra. Ao vibrar as", "saliências da cabeça, cria ondas na", "água ou tremores parecidos com", "terremotos em terra."],
    "sPokedexText_SEISMITOAD": ["Aumenta o poder dos socos vibrando as", "saliências dos punhos. Também dispara", "líquido paralisante pelas", "saliências da cabeça."],
    "sPokedexText_THROH": ["Quando aperta o cinto, fica mais", "forte. Throh selvagens tecem o próprio", "cinto com vinhas. Troca de cinto", "ao ficar mais forte."],
    "sPokedexText_SAWK": ["O som de Sawk socando rochas e árvores", "pode ser ouvido desde as montanhas", "onde treinam. Atrapalhe o treino", "e ele se enfurece."],
    "sPokedexText_SEWADDLE": ["Mastiga folhas e as costura com o fio", "pegajoso que sai de sua boca. Como", "este Pokemon faz as próprias roupas,", "é mascote de estilistas."],
    "sPokedexText_SWADLOON": ["Florestas onde Swadloon vivem têm", "folhagem soberba, pois os nutrientes", "que eles criam das folhas caídas", "nutrem as plantas."],
    "sPokedexText_LEAVANNY": ["Aquece os ovos com o calor de folhas", "em fermentação. Também tece com folhas", "agasalhos quentes para os", "pequenos Sewaddle."],
    "sPokedexText_VENIPEDE": ["Com as antenas da cabeça e da cauda,", "capta vibrações do ar para localizar a", "presa. É agressivo e não desiste", "jamais de uma luta."],
    "sPokedexText_WHIRLIPEDE": ["Fica parado, juntando energia para", "evoluir. Mas, se atacado, gira o corpo", "em alta velocidade como uma roda", "e investe no rival."],
    "sPokedexText_SCOLIPEDE": ["Com movimentos rápidos, persegue os", "rivais, atacando sem trégua com os", "chifres até vencer. Depois finaliza", "com veneno."],
    "sPokedexText_COTTONEE": ["Quando encontra outros da sua espécie,", "todos grudam uns nos outros. Quando se", "juntam muitos, a massa parece", "uma nuvem."],
    "sPokedexText_WHIMSICOTT": ["Cavalga o vento e se enfia nas casas.", "Depois de encher o cômodo de algodão", "e bagunça, dá risadinhas", "e vai embora."],
    "sPokedexText_PETILIL": ["Aparando com frequência as folhas da", "cabeça, este Pokemon cresce belo e", "roliço. As folhas amargas renovam", "quem as come."],
    "sPokedexText_LILLIGANT": ["Até Treinadores veteranos penam para", "fazer sua bela flor desabrochar. Ela", "murcha se o Treinador não", "cuida bem dele."],
    "sPokedexText_BASCULIN": ["Já foi uma fonte comum de alimento.", "A carne do Basculin vermelho é mais", "gorda; a do azul tem sabor", "mais leve."],
    "sPokedexText_SANDILE": ["Esconde-se na areia e abocanha as", "pernas de qualquer presa que pise nele", "sem perceber. Seu lugar favorito", "é a areia quente."],
    "sPokedexText_KROKOROK": ["Movem-se em grupos pequenos. Graças à", "membrana especial que cobre os olhos,", "enxergam no escuro total."],
    "sPokedexText_KROOKODILE": ["Pokemon muito violentos, nunca deixam", "a presa escapar. Suas mandíbulas são", "tão fortes que esmagam a carcaça", "de um carro."],
    "sPokedexText_DARUMAKA": ["Quando seu fogo interno arde, não se", "aquieta e corre por todo lado. Quando", "o fogo diminui, recolhe os membros", "ao corpo e dorme."],
    "sPokedexText_DARMANITAN": ["Ferido, para de se mover. Fica imóvel", "como pedra para meditar, afiando", "a mente e o espírito."],
    "sPokedexText_MARACTUS": ["Regiões áridas são seu habitat. Ao se", "mover com ritmo, faz um som parecido", "com maracas, assustando os Pokemon,", "que fogem."],
    "sPokedexText_DWEBBLE": ["Abre um buraco numa pedra de tamanho", "adequado. Se a rocha quebra, o Pokemon", "fica agitado até encontrar", "uma substituta."],
    "sPokedexText_CRUSTLE": ["Disputando território, Crustle lutam", "ferozmente. Aquele cuja rocha se", "quebra perde a batalha e começa", "a enfraquecer."],
    "sPokedexText_SCRAGGY": ["Sua pele tem elasticidade de borracha:", "ele reduz o dano puxando a pele até o", "pescoço para se defender. Dá", "cabeçadas certeiras."],
    "sPokedexText_SCRAFTY": ["Em grupos, batem em qualquer um que", "entre em seu território. Quem tem a", "maior crista é o líder", "do bando."],
    "sPokedexText_SIGILYPH": ["Guardiões de uma cidade antiga, voam", "sempre pela mesma rota, vigiando", "contra invasores. Usam seu misterioso", "poder psíquico."],
    "sPokedexText_YAMASK": ["Estes Pokemon surgiram de espíritos de", "pessoas sepultadas em eras passadas.", "Cada um carrega uma máscara que era", "seu antigo rosto."],
    "sPokedexText_COFAGRIGUS": ["Ladrões de túmulos que os confundem", "com caixões de verdade e chegam perto", "acabam presos dentro de seus corpos", "cobertos de ouro."],
    "sPokedexText_TIRTOUGA": ["Tido como o ancestral da maioria dos", "Pokemon tartaruga, vivia em mares", "quentes há uns cem milhões de anos.", "Foi restaurado de um fóssil."],
    "sPokedexText_CARRACOSTA": ["Vivem tanto no oceano quanto em", "terra. A força incrível da mandíbula", "permite mastigar vigas de aço", "e rochas."],
    "sPokedexText_ARCHEN": ["Tido como o ancestral de todos os", "Pokemon pássaros. O próprio Archen não", "voava: movia-se saltando de copa", "em copa."],
    "sPokedexText_ARCHEOPS": ["São inteligentes e cooperam para caçar.", "Quando um Archeops encurralava a", "presa, outro atacava."],
    "sPokedexText_TRUBBISH": ["Empanturra-se de lixo até encher o", "estômago. Depois arrota gás tóxico.", "Uma baforada azarada desse gás leva", "alguém ao hospital."],
    "sPokedexText_GARBODOR": ["Cuidado com o líquido venenoso que", "dispara do braço direito. Basta um", "pingo em você para sentir o", "efeito do veneno."],
    "sPokedexText_ZORUA": ["Para se proteger do perigo, escondem a", "verdadeira identidade se transformando", "em pessoas e Pokemon."],
    "sPokedexText_ZOROARK": ["Os laços entre estes Pokemon são muito", "fortes. Protege o bando enganando os", "oponentes e defende a toca com", "paisagens ilusórias."],
    "sPokedexText_MINCCINO": ["Estes Pokemon preferem um habitat", "limpo. Cumprimentam-se esfregando as", "caudas um no outro, sempre", "muito bem escovadas."],
    "sPokedexText_CINCCINO": ["Seu pelo branco é incrível ao toque.", "O corpo de Cinccino é coberto por um", "óleo especial que repele poeira", "e desvia golpes."],
    "sPokedexText_GOTHITA": ["Observam fixamente Treinadores e", "Pokemon. Ao que parece, Gothita", "enxergam algo que mais", "ninguém vê."],
    "sPokedexText_GOTHORITA": ["A luz das estrelas é a fonte do seu", "poder. Usam hipnose para controlar", "pessoas e Pokemon", "adormecidos."],
    "sPokedexText_GOTHITELLE": ["Céus estrelados a milhares de", "anos-luz são visíveis no espaço", "distorcido por seu intenso poder", "psíquico."],
    "sPokedexText_SOLOSIS": ["Como seus corpos são envoltos num", "líquido especial, aguentam qualquer", "ambiente, por mais severo", "que seja."],
    "sPokedexText_DUOSION": ["Quando seus cérebros, agora divididos", "em dois, pensam os mesmos pensamentos,", "estes Pokemon exibem seu poder", "psíquico máximo."],
    "sPokedexText_REUNICLUS": ["Usam poder psíquico para controlar os", "braços, feitos de um líquido especial.", "Seus socos têm força", "esmagadora."],
    "sPokedexText_DUCKLETT": ["Estes Pokemon pássaros são ótimos", "mergulhadores. Nadam melhor do que", "voam e mergulham atrás de", "musgo-pavão, seu alimento."],
    "sPokedexText_SWANNA": ["Apesar da aparência elegante, batem as", "asas com força e voam milhares de", "quilômetros. O do centro do bando", "é o líder."],
    "sPokedexText_VANILLITE": ["A temperatura do seu hálito é de 50", "graus negativos. Criam cristais de", "neve e fazem nevar ao seu redor."],
    "sPokedexText_VANILLISH": ["Vanillish existe desde a Era do Gelo.", "Controla partículas de gelo e congela", "os rivais para detê-los."],
    "sPokedexText_VANILLUXE": ["Cada uma das duas cabeças tem um", "cérebro. Quando elas concordam, ataca", "os inimigos exalando uma", "nevasca violenta."],
    "sPokedexText_DEERLING": ["Deerling têm aromas diferentes", "conforme a estação. Nesta forma, têm", "um cheiro doce e suave que", "permanece no nariz."],
    "sPokedexText_SAWSBUCK": ["Sawsbuck na Forma Outono são famosos", "pelo pavio bem curto. Os machos", "brigam entre si sem parar."],
    "sPokedexText_EMOLGA": ["Plana usando sua membrana parecida com", "uma capa. Assa BERRIES e Pokemon", "insetos com choques das bolsas", "elétricas das bochechas."],
    "sPokedexText_KARRABLAST": ["Quando se sentem ameaçados, cospem um", "líquido ácido para afastar os", "agressores. Por algum motivo, evoluem", "perto de Shelmet."],
    "sPokedexText_ESCAVALIER": ["Vestindo a carapaça que roubaram de", "Shelmet, defendem-se e atacam com duas", "lanças. A armadura de aço protege", "seu corpo macio."],
    "sPokedexText_FOONGUS": ["Atrai Pokemon com seu padrão idêntico", "a uma POKé BALL e então libera", "esporos venenosos."],
    "sPokedexText_AMOONGUSS": ["Atrai a presa dançando e acenando com", "seus chapéus que lembram POKé BALLS.", "Poucos Pokemon caem", "no truque."],
    "sPokedexText_FRILLISH": ["Se seus braços de véu atordoam e", "envolvem um oponente, ele é arrastado", "a 8 km abaixo da superfície,", "até sua toca."],
    "sPokedexText_JELLICENT": ["Impulsionam-se expelindo a água do mar", "absorvida pelo corpo. Dizem que há no", "fundo do mar um castelo de navios", "afundados por Jellicent."],
    "sPokedexText_ALOMOMOLA": ["Quando acham um Pokemon ferido, eles o", "abraçam e o levam até a praia.", "A membrana especial de Alomomola", "cura ferimentos."],
    "sPokedexText_JOLTIK": ["Como não geram a própria eletricidade,", "grudam em Pokemon grandes e absorvem", "eletricidade estática, guardando-a", "numa bolsa."],
    "sPokedexText_GALVANTULA": ["Cria barreiras de seda eletrificada", "que atordoam os rivais. Isso funciona", "como arma e também como", "defesa sólida."],
    "sPokedexText_FERROSEED": ["Absorve o ferro que encontra na rocha", "enquanto se prende ao teto das", "cavernas. Dispara espinhos", "quando ameaçado."],
    "sPokedexText_FERROTHORN": ["Luta girando suas três antenas", "espinhosas e disparando espinhos.", "Um golpe desses espinhos de aço reduz", "um pedregulho a pó."],
    "sPokedexText_KLINK": ["Dois corpos formam um par fixo. As", "duas mini-engrenagens que se encaixam", "são predeterminadas e rejeitam", "qualquer outra."],
    "sPokedexText_KLANG": ["Uma mini-engrenagem e uma engrenagem", "grande formam seu corpo. Gira as", "mini-engrenagens em alta velocidade", "e as dispara."],
    "sPokedexText_KLINKLANG": ["Seu núcleo vermelho funciona como", "tanque de energia. Ele gira em alta", "velocidade para uma carga", "rápida de energia."],
    "sPokedexText_TYNAMO": ["Estes Pokemon se movem em cardumes.", "Um sozinho emite só um fiapo de", "eletricidade, então o grupo se junta", "para soltar choques."],
    "sPokedexText_EELEKTRIK": ["Estes Pokemon têm um apetite enorme.", "Enrola-se na presa e a paralisa com a", "eletricidade das manchas redondas dos", "flancos. Depois devora."],
    "sPokedexText_EELEKTROSS": ["Rastejam para fora do oceano usando os", "braços. Atacam presas na praia e as", "arrastam de volta", "para o mar."],
    "sPokedexText_ELGYEM": ["Aperta psiquicamente o cérebro do", "rival, causando dores de cabeça", "insuportáveis. Rumores ligam sua", "origem a um OVNI."],
    "sPokedexText_BEHEEYEM": ["Consegue manipular a memória do", "oponente. Ao que parece, comunica-se", "piscando as luzes coloridas", "de seus dedos."],
    "sPokedexText_LITWICK": ["Enquanto acende uma luz e finge guiar", "o caminho, Litwick absorve a força", "vital de pessoas e Pokemon."],
    "sPokedexText_LAMPENT": ["Este Pokemon sinistro é temido. Vagueia", "pelas cidades em busca dos espíritos", "dos caídos, que absorve", "como combustível."],
    "sPokedexText_CHANDELURE": ["Ser consumido pela chama de Chandelure", "queima o espírito, deixando o corpo", "para trás."],
    "sPokedexText_AXEW": ["Marcam o território deixando cortes", "nas árvores com as presas. Se uma", "presa quebra, outra cresce rápido,", "mais dura e firme."],
    "sPokedexText_FRAXURE": ["Suas presas estilhaçam rochas. Uma", "presa quebrada não cresce de novo, por", "isso ele as afia com zelo em pedras", "de rio após as lutas."],
    "sPokedexText_HAXORUS": ["São gentis, mas implacáveis ao", "defender o território. Suas presas", "robustas continuam afiadas mesmo", "cortando vigas de aço."],
    "sPokedexText_CUBCHOO": ["Seu nariz vive escorrendo. O muco é um", "barômetro de saúde: quando saudável, o", "muco é pegajoso e seus golpes de gelo", "ganham força."],
    "sPokedexText_BEARTIC": ["Congela o próprio hálito para criar", "presas e garras de gelo para lutar.", "Muito hábil na água, nada pelos", "mares do norte."],
    "sPokedexText_CRYOGONAL": ["Nascem em nuvens de neve. Quando sua", "temperatura sobe, vira vapor e some.", "Quando ela baixa, volta a", "ser gelo."],
    "sPokedexText_SHELMET": ["Quando atacado, defende-se fechando a", "tampa de sua concha. Evolui ao ser", "banhado por uma energia parecida", "com eletricidade."],
    "sPokedexText_ACCELGOR": ["Quando seu corpo seca, enfraquece.", "Para evitar a desidratação, envolve-se", "em muitas camadas de", "membrana fina."],
    "sPokedexText_STUNFISK": ["Esconde-se na lama do litoral e", "espera. Quando a presa o toca, solta", "uma descarga elétrica, sem deixar", "de sorrir."],
    "sPokedexText_MIENFOO": ["Dominaram combos elegantes. Ao se", "concentrarem, seus golpes ficam mais", "rápidos e precisos."],
    "sPokedexText_MIENSHAO": ["Usam o longo pelo dos braços como", "chicote para golpear os oponentes.", "Seus ataques são tão rápidos que", "nem se consegue ver."],
    "sPokedexText_DRUDDIGON": ["Aquece o corpo absorvendo a luz do sol", "com as asas. Quando a temperatura do", "corpo cai, não consegue", "mais se mover."],
    "sPokedexText_GOLETT": ["Acredita-se que estes Pokemon foram", "criados pela ciência de uma", "civilização antiga e misteriosa. Está", "ativo há milhares de anos."],
    "sPokedexText_GOLURK": ["Golurk foram criados para proteger", "pessoas e Pokemon por uma civilização", "antiga. Remover o selo do peito o", "faz descontrolar-se."],
    "sPokedexText_PAWNIARD": ["Ignorando os ferimentos, atacam em", "grupo cravando as lâminas que cobrem", "seus corpos na presa."],
    "sPokedexText_BISHARP": ["Este Pokemon impiedoso comanda um", "grupo de Pawniard que acossa a presa", "até imobilizá-la. Ele luta para", "se tornar o chefe."],
    "sPokedexText_BOUFFALANT": ["Seu pelo fofo absorve o dano, mesmo", "quando acertam o rival com uma", "cabeçada feroz capaz de descarrilar", "um trem."],
    "sPokedexText_RUFFLET": ["Com as garras afiadas, este Pokemon", "perfura a presa e depois a bica.", "Embora também coma BERRIES, é", "carnívoro por natureza."],
    "sPokedexText_BRAVIARY": ["Pelo bem dos amigos, este bravo", "guerreiro dos céus não para de lutar,", "mesmo ferido. Quanto mais cicatrizes,", "mais respeitado."],
    "sPokedexText_VULLABY": ["Ainda não voa e precisa esperar as", "asas se desenvolverem. Protege o", "traseiro com ossos juntados", "por Mandibuzz."],
    "sPokedexText_MANDIBUZZ": ["Enfeitam-se belamente com ossos.", "Dizem que é um esforço para atrair", "machos, mas nenhum Mandibuzz macho", "jamais foi encontrado."],
    "sPokedexText_HEATMOR": ["Puxa ar pela cauda, transforma-o em", "fogo e o usa como língua. Derrete a", "armadura de aço de Durant e devora", "seu interior."],
    "sPokedexText_DURANT": ["Durant cavam ninhos nas montanhas.", "Cada indivíduo tem um papel ao", "expulsar Heatmor, seu", "predador natural."],
    "sPokedexText_DEINO": ["Sem visão, não percebe o que o cerca:", "esbarra nas coisas e come tudo que se", "move. Aproximar-se dele é perigoso."],
    "sPokedexText_ZWEILOUS": ["Depois de comer toda a comida do seu", "território, muda-se para outra área.", "As duas cabeças não se", "dão nada bem."],
    "sPokedexText_HYDREIGON": ["Este Pokemon brutal cruza os céus com", "suas seis asas. As cabeças dos braços", "não têm cérebro, mas", "devoram tudo."],
    "sPokedexText_LARVESTA": ["Acreditava-se que este Pokemon nasceu", "do sol. Expele fogo pelos chifres e se", "envolve num casulo de fogo", "para evoluir."],
    "sPokedexText_VOLCARONA": ["Quando cinzas vulcânicas escureceram a", "atmosfera, ele apareceu e salvou os", "Pokemon do frio: o fogo de Volcarona", "substituiu o sol."],
    "sPokedexText_COBALION": ["Tem corpo e coração de aço. Este", "Pokemon lendário lutou contra humanos", "para proteger Pokemon. É calmo", "e sereno."],
    "sPokedexText_TERRAKION": ["Citado em lendas, este Pokemon usou", "seu poder fenomenal para destruir um", "castelo e proteger os Pokemon", "em perigo."],
    "sPokedexText_VIRIZION": ["De sua cabeça brotam chifres afiados", "como lâminas. Lendas dizem que usava", "movimentos de redemoinho para", "confundir os rivais."],
    "sPokedexText_TORNADUS": ["Um exemplo do que se chama “mudança", "de forma”. Tornadus já foi visto", "cruzando o oceano", "nesta forma."],
    "sPokedexText_THUNDURUS": ["Pulveriza os rivais com chuvas de", "raios devastadores lançados do cordão", "de esferas de sua cauda."],
    "sPokedexText_RESHIRAM": ["Este Pokemon aparece em lendas. Lança", "chamas ao ar pela cauda, queimando", "tudo ao redor. Ajuda quem busca", "construir um mundo de verdade."],
    "sPokedexText_ZEKROM": ["Este Pokemon lendário pode calcinar o", "mundo com relâmpagos. Tem na cauda um", "gerador que cria eletricidade."],
    "sPokedexText_LANDORUS": ["Landorus cruza os céus nesta forma,", "concedendo fartas colheitas à terra e", "ganhando a reverência", "do povo."],
    "sPokedexText_KYUREM": ["Este lendário Pokemon de gelo espera um", "herói para preencher as partes que", "faltam de seu corpo com", "verdade ou ideais."],
    "sPokedexText_KELDEO": ["Quando está decidido, seu corpo se", "enche de poder e ele fica mais veloz.", "Cruza a água correndo,", "quase voando."],
    "sPokedexText_MELOETTA": ["As melodias cantadas por Meloetta têm", "o poder de alegrar ou entristecer os", "Pokemon que as ouvem. Inspiraram", "canções famosas."],
    "sPokedexText_GENESECT": ["Genesect vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_CHESPIN": ["Os espinhos de sua cabeça costumam ser", "macios. Quando ele os flexiona, as", "pontas ficam duras e afiadas a ponto", "de furar pedra."],
    "sPokedexText_QUILLADIN": ["Fortalecem a casca robusta que cobre", "seus corpos trombando uns nos outros.", "São gentis e nunca iniciam", "uma briga."],
    "sPokedexText_CHESNAUGHT": ["Protege os aliados do perigo com o", "próprio corpo. Em postura defensiva,", "com os punhos diante do rosto, aguenta", "até uma explosão."],
    "sPokedexText_FENNEKIN": ["Enquanto caminha, mastiga um graveto", "para se encher de energia, como um", "lanche. Sopra ar quente", "pelas orelhas."],
    "sPokedexText_BRAIXEN": ["Braixen tem um graveto espetado na", "cauda. Quando o arranca, o atrito o", "acende, e ele luta com o", "graveto em chamas."],
    "sPokedexText_DELPHOX": ["Contempla a chama na ponta de seu", "galho para entrar em estado de foco e", "assim enxergar o futuro."],
    "sPokedexText_FROAKIE": ["Protege a pele cobrindo o corpo com", "bolhas que secreta pelo peito e pelas", "costas. Parece distraído, mas vigia", "tudo com atenção."],
    "sPokedexText_FROGADIER": ["Arremessa pedrinhas cobertas de bolhas", "com controle preciso, acertando latas", "a mais de 30 metros."],
    "sPokedexText_GRENINJA": ["Greninja vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_BUNNELBY": ["Tem orelhas como pás. Cavar buracos as", "fortalece tanto que elas cortam raízes", "grossas sem esforço."],
    "sPokedexText_DIGGERSBY": ["Com as orelhas poderosas, reduz rocha", "maciça a cascalho. É uma grande ajuda", "em obras e construções."],
    "sPokedexText_FLETCHLING": ["Este Pokemon amável é fácil de", "treinar. Mas, na batalha, mostra seu", "lado feroz: é impiedoso com", "os inimigos."],
    "sPokedexText_FLETCHINDER": ["Expele pelo bico brasas que incendeiam", "o capim alto. Então se lança sobre as", "presas assustadas que", "saem correndo."],
    "sPokedexText_TALONFLAME": ["No calor de uma batalha empolgante,", "espalha brasas pelas frestas das penas", "e alça voo."],
    "sPokedexText_SCATTERBUG": ["Scatterbug vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_SPEWPA": ["Spewpa vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_VIVILLON": ["Seu padrão depende do clima e do", "relevo da terra onde nasceu. Esta", "forma vem de terras banhadas", "pela luz."],
    "sPokedexText_LITLEO": ["Deixam o bando por conta própria e", "vivem sozinhos para ficarem mais", "fortes. São filhotes de", "sangue quente."],
    "sPokedexText_PYROAR": ["O macho com a maior juba de fogo é o", "líder do bando. As fêmeas protegem os", "filhotes do grupo."],
    "sPokedexText_FLABEBE": ["Este Flabebe monta numa flor vermelha.", "Logo após nascer, este Pokemon sai", "voando em busca de uma flor", "de que goste."],
    "sPokedexText_FLOETTE": ["Este Pokemon usa ondas de luz vermelha", "para verter sua energia nas flores e", "despertar o potencial", "latente delas."],
    "sPokedexText_FLORGES": ["Este Pokemon cria um esplêndido jardim", "de flores em seu território. Extrai o", "poder das flores vermelhas", "de seu pescoço."],
    "sPokedexText_SKIDDO": ["Com sol e água, não precisa comer,", "pois gera energia com as folhas das", "costas. É dócil desde", "os tempos antigos."],
    "sPokedexText_GOGOAT": ["Sabe como seu Treinador se sente por", "mudanças sutis no jeito de segurar", "seus chifres. É possível", "cavalgá-lo."],
    "sPokedexText_PANCHAM": ["A folha em sua boca não serve para", "nada, além de fazê-lo parecer", "descolado. Esforça-se para", "ser levado a sério."],
    "sPokedexText_PANGORO": ["Ostenta força física soberba. Quem", "quiser se tornar Treinador de Pangoro", "não tem escolha senão conversar", "com os punhos."],
    "sPokedexText_FURFROU": ["Furfrou vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_ESPURR": ["Tem energia psíquica para explodir", "tudo num raio de 90 metros. O órgão", "que emite esse poder fica protegido", "por suas orelhas."],
    "sPokedexText_MEOWSTIC": ["As fêmeas são um pouco mais egoístas e", "agressivas que os machos. Se não", "conseguem o que querem, atormentam", "com poder psíquico."],
    "sPokedexText_HONEDGE": ["Se alguém ousa segurar seu cabo, ele", "enrola um pano azul no braço da pessoa", "e drena sua força vital."],
    "sPokedexText_DOUBLADE": ["Quando Honedge evolui, divide-se em", "duas espadas. Os padrões complexos de", "ataque das duas lâminas são", "impossíveis de deter."],
    "sPokedexText_AEGISLASH": ["Era uma vez um rei com um Aegislash", "que reinava sobre a terra. Seu Pokemon", "drenou sua vida, e o reino", "caiu com ele."],
    "sPokedexText_SPRITZEE": ["No passado, em vez de usar perfume, as", "damas da realeza levavam um Spritzee", "que exalava a fragrância", "que desejassem."],
    "sPokedexText_AROMATISSE": ["Seu aroma é tão avassalador que, a", "menos que o Treinador goste muito do", "cheiro, terá dificuldade em", "andar ao seu lado."],
    "sPokedexText_SWIRLIX": ["Como só come doces, seu pelo é doce e", "grudento como algodão-doce.", "Solta fios pegajosos para", "prender rivais."],
    "sPokedexText_SLURPUFF": ["Slurpuff distingue até os aromas mais", "tênues. Usa seu olfato sensível para", "ajudar confeiteiros em", "suas criações."],
    "sPokedexText_INKAY": ["Pisca os pontos luminosos do corpo,", "drenando a vontade de lutar do", "oponente. Aproveita para fugir", "e se esconder."],
    "sPokedexText_MALAMAR": ["Atrai a presa com movimentos", "hipnóticos, depois a envolve com os", "tentáculos antes de finalizá-la", "com digestivos."],
    "sPokedexText_BINACLE": ["Esticam-se e contraem, arrastando suas", "rochas junto em saltos ousados. Dois", "vivem na mesma rocha."],
    "sPokedexText_BARBARACLE": ["As pernas e mãos de Barbaracle têm", "mente própria e se movem de forma", "independente. Mas costumam seguir as", "ordens da cabeça."],
    "sPokedexText_SKRELP": ["Camuflado de alga podre, esconde-se", "dos rivais enquanto junta forças para", "a evolução. Borrifa veneno líquido", "em quem o ameaça."],
    "sPokedexText_DRAGALGE": ["Seu veneno corrói até o casco de um", "petroleiro. Contam-se histórias de", "navios que entram em seus mares e", "nunca mais voltam."],
    "sPokedexText_CLAUNCHER": ["Com expulsões controladas de gás", "interno, dispara água como um tiro de", "pistola, capaz de partir", "rocha."],
    "sPokedexText_CLAWITZER": ["Expelindo água pelo bocal atrás de sua", "garra enorme, move-se a 110 km/h.", "Lançam bolas d'água", "nas presas."],
    "sPokedexText_HELIOPTILE": ["Fazem do deserto seu lar. Geram a", "própria energia tomando sol, então", "comer não é essencial", "para eles."],
    "sPokedexText_HELIOLISK": ["Um único Heliolisk gera eletricidade", "suficiente para abastecer um", "arranha-céu. Abre o babado do pescoço", "para carregar."],
    "sPokedexText_TYRUNT": ["Suas mandíbulas imensas têm força", "destrutiva para mastigar um carro.", "Se algo o desagrada, responde", "com birra violenta."],
    "sPokedexText_TYRANTRUM": ["Graças às mandíbulas gigantescas, que", "rasgavam placas grossas de metal como", "papel, era invencível no mundo", "antigo em que viveu."],
    "sPokedexText_AMAURA": ["Este Pokemon antigo foi restaurado de", "uma parte do corpo congelada no gelo", "por mais de 100 milhões", "de anos."],
    "sPokedexText_AURORUS": ["Com os cristais em forma de losango do", "corpo, cria num instante uma muralha", "de gelo para se defender", "dos ataques."],
    "sPokedexText_SYLVEON": ["Suas antenas em forma de fita emitem", "uma aura que enfraquece a hostilidade", "da presa, baixando a", "guarda dela."],
    "sPokedexText_HAWLUCHA": ["Com as asas, controla sua posição no", "ar. Suas habilidades de luta e os", "golpes vindos do alto o tornam", "temível."],
    "sPokedexText_DEDENNE": ["Seus bigodes servem de antenas.", "Enviando e recebendo ondas elétricas,", "comunica-se com outros a", "grandes distâncias."],
    "sPokedexText_CARBINK": ["Nascido das altas temperaturas e", "pressões do subsolo, defende-se", "disparando feixes da joia", "de seu corpo."],
    "sPokedexText_GOOMY": ["Sua proteção é a membrana mucosa", "cheia de germes que o cobre. Quem o", "toca precisa lavar muito", "bem as mãos."],
    "sPokedexText_SLIGGOO": ["O muco deste Pokemon dissolve", "qualquer coisa. Sem dentes, borrifa", "muco na presa e a sorve depois de", "bem dissolvida."],
    "sPokedexText_GOODRA": ["Sofre provocações por ser manso. Mas", "aí quem o provocou sente a força total", "de seus chifres e de um", "bom golpe."],
    "sPokedexText_KLEFKI": ["Estes colecionadores de chaves ameaçam", "qualquer agressor chacoalhando suas", "chaves com fúria. Ele entra nas casas", "para roubar chaves."],
    "sPokedexText_PHANTUMP": ["Segundo a lenda, um remédio para curar", "qualquer doença pode ser feito", "colhendo as folhas verdes da sua", "cabeça e fervendo-as."],
    "sPokedexText_TREVENANT": ["Através das raízes, controla outras", "árvores. Uma maldição mortal cai sobre", "quem derruba árvores na floresta", "onde ele vive."],
    "sPokedexText_PUMPKABOO": ["Ao levar espíritos para o outro mundo,", "os Pumpkaboo grandes preferem os", "espíritos de adultos aos", "de crianças."],
    "sPokedexText_GOURGEIST": ["Um Pumpkaboo de porte grande evolui", "para um Gourgeist de porte grande.", "Suas proporções corporais passam", "aos descendentes."],
    "sPokedexText_BERGMITE": ["Bloqueia os ataques dos oponentes com", "o gelo que escuda seu corpo. Usa ar", "frio para reparar rachaduras", "no mesmo instante."],
    "sPokedexText_AVALUGG": ["Vários Bergmite apinhados em suas", "costas o fazem parecer um", "porta-aviões de gelo. Seu corpanzil", "esmaga o que pisa."],
    "sPokedexText_NOIBAT": ["Vivem em cavernas escuras como breu.", "Até um lutador parrudo fica tonto e", "sem equilíbrio diante de suas ondas", "de 200.000 hertz."],
    "sPokedexText_NOIVERN": ["Voam em noites sem lua e atacam presas", "descuidadas. As ondas ultrassônicas", "que emite pelas orelhas reduzem", "rochas a cacos."],
    "sPokedexText_XERNEAS": ["Xerneas vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_YVELTAL": ["Quando sua vida chega ao fim, suas", "asas e cauda se abrem e brilham em", "vermelho, e ele absorve a energia", "vital dos seres vivos."],
    "sPokedexText_ZYGARDE": ["Zygarde vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_DIANCIE": ["Uma transformação repentina de", "Carbink. Dizem que seu corpo rosa e", "cintilante é a visão mais linda", "que existe."],
    "sPokedexText_HOOPA": ["É a verdadeira forma de Hoopa, com o", "poder selado. Os anéis que carrega", "transportam o que passa", "por eles."],
    "sPokedexText_VOLCANION": ["Solta rolos de vapor pelos braços de", "suas costas e some na névoa densa.", "Dizem que vive nas", "montanhas."],
    "sPokedexText_ROWLET": ["Este Pokemon desconfiado usa", "fotossíntese para juntar energia de", "dia e fica ativo à noite. Plana em", "silêncio até a presa."],
    "sPokedexText_DARTRIX": ["Meio dândi, passa o tempo livre", "alisando as asas. A preocupação com", "qualquer sujeira na plumagem pode", "custar a batalha."],
    "sPokedexText_DECIDUEYE": ["Decidueye é frio e cauteloso. Dispara", "penas-flecha das asas com tanta", "precisão que atravessam um seixo", "a cem metros."],
    "sPokedexText_LITTEN": ["Ao se lamber, acumula pelos no", "estômago. Ele os incendeia e cospe", "bolas de fogo flamejantes."],
    "sPokedexText_TORRACAT": ["Na garganta, carrega um guizo de fogo.", "O guizo soa vivo sempre que este", "Pokemon cospe chamas."],
    "sPokedexText_INCINEROAR": ["Este Pokemon tem índole violenta e", "egoísta. Sem vontade de obedecer,", "ignora as ordens do Treinador", "como se nada fosse."],
    "sPokedexText_POPPLIO": ["Este Pokemon sopra fluidos pelo nariz,", "criando balões para arremessar nos", "rivais. Pratica com afinco todos", "os dias."],
    "sPokedexText_BRIONNE": ["Importa-se muito com os companheiros.", "Quando o Treinador está triste,", "apresenta uma dança animada em", "sequência para alegrá-lo."],
    "sPokedexText_PRIMARINA": ["Controla seus balões d'água com o", "canto. A melodia é aprendida com os da", "sua espécie e passada de geração", "em geração."],
    "sPokedexText_PIKIPEK": ["Este Pokemon come BERRIES, e as", "sementes que sobram viram munição para", "os ataques que dispara", "pelo bico."],
    "sPokedexText_TRUMBEAK": ["Dobrando o bico, produz vários tipos", "de chamado, virando um vizinho", "barulhento. Come BERRIES e guarda", "as sementes."],
    "sPokedexText_TOUCANNON": ["Em batalha, os gases internos do bico", "se inflamam, disparando sementes com", "força explosiva capaz de pulverizar", "pedregulhos."],
    "sPokedexText_YUNGOOS": ["Com as presas afiadas, morde qualquer", "coisa. Vagueia numa busca sem fim por", "comida. Ao anoitecer, desaba e dorme", "onde estiver."],
    "sPokedexText_GUMSHOOS": ["Gumshoos vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_GRUBBIN": ["Costumam se reunir perto de lugares", "frequentados por Pokemon elétricos,", "para evitar serem atacados por", "Pokemon pássaros."],
    "sPokedexText_CHARJABUG": ["Da comida que digere, gera", "eletricidade e a guarda em sua bolsa", "elétrica. Em acampamentos, serve", "de gerador."],
    "sPokedexText_VIKAVOLT": ["Vikavolt vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_CRABRAWLER": ["Protegendo os pontos fracos com as", "pinças, procura uma brecha e dispara", "socos. Quando perde, espuma pela", "boca e desmaia."],
    "sPokedexText_CRABOMINABLE": ["Mirava o topo, mas se perdeu e foi", "parar numa montanha nevada. Forçado a", "aguentar o frio, este Pokemon se", "cobriu de pelos."],
    "sPokedexText_ORICORIO": ["Esta forma de Oricorio bebeu néctar", "rosa. Eleva a mente com os passos", "suaves de sua dança e libera sua", "energia psíquica."],
    "sPokedexText_CUTIEFLY": ["Miríades de Cutiefly esvoaçam sobre a", "cabeça de pessoas com auras parecidas", "com as de flores. Ele identifica", "essas auras."],
    "sPokedexText_RIBOMBEE": ["Ribombee vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_ROCKRUFF": ["Rockruff vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_LYCANROC": ["Estes Pokemon têm qualidades calmas e", "ferozes. Dizem que esta forma de", "Lycanroc é a mais trabalhosa", "de criar."],
    "sPokedexText_WISHIWASHI": ["Individualmente, são incrivelmente", "fracos. É se reunindo em cardumes que", "conseguem enfrentar", "oponentes."],
    "sPokedexText_MAREANIE": ["É visto rastejando em praias e fundos", "do mar. O coral que cresce na cabeça", "de Corsola é, para ele, um banquete", "cinco estrelas."],
    "sPokedexText_TOXAPEX": ["Quem é atingido pelo veneno de Toxapex", "sofre dores intensas por três dias e", "três noites. Mesmo curado, a dor", "ainda volta às vezes."],
    "sPokedexText_MUDBRAY": ["A lama presa aos cascos de Mudbray", "melhora sua tração e seu galope", "poderoso. Comer terra e fazer lama", "são seus passatempos."],
    "sPokedexText_MUDSDALE": ["Seus coices pesados e cobertos de lama", "são sua melhor arma. Reduz caminhões", "grandes a sucata sem nem", "suar."],
    "sPokedexText_DEWPIDER": ["Rasteja para a terra em busca de", "comida. Ao topar com inimigos ou", "presas, atira bolhas d'água", "com a cabeça."],
    "sPokedexText_ARAQUANID": ["Araquanid vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_FOMANTIS": ["De dia, dorme e absorve luz. Exalam um", "aroma doce e refrescante. Cutiefly", "costumam se reunir perto dele", "enquanto dorme."],
    "sPokedexText_LURANTIS": ["Lurantis vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_MORELULL": ["Cochilando o dia inteiro, nutre-se", "sugando as raízes das árvores.", "Desperta ao cair da noite e vagueia", "espalhando esporos."],
    "sPokedexText_SHIINOTIC": ["Florestas onde Shiinotic vivem são", "traiçoeiras à noite. Pessoas confusas", "por suas luzes estranhas nunca mais", "acham o caminho de casa."],
    "sPokedexText_SALANDIT": ["Queima seus fluidos corporais criando", "um gás venenoso de cheiro doce.", "Quando os inimigos ficam zonzos ao", "inalá-lo, ele ataca."],
    "sPokedexText_SALAZZLE": ["Salazzle vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_STUFFUL": ["Apesar da aparência adorável, quando", "se zanga e se debate, seus braços e", "pernas derrubam lutadores", "profissionais."],
    "sPokedexText_BEWEAR": ["Este Pokemon tem o hábito de abraçar", "os companheiros. Muitos Treinadores já", "partiram deste mundo num abraço", "forte demais."],
    "sPokedexText_BOUNSWEET": ["Um aroma delicioso emana do seu corpo.", "O suor de Bounsweet pode ser diluído", "num suco no ponto certo", "de doçura."],
    "sPokedexText_STEENEE": ["As sépalas da cabeça se desenvolveram", "para proteger o corpo. São tão duras", "que bicadas de Pokemon pássaros", "não fazem nada."],
    "sPokedexText_TSAREENA": ["Suas pernas longas e marcantes não são", "só enfeite: servem para chutar com", "habilidade. Ri do rival", "que derrota."],
    "sPokedexText_COMFEY": ["Prende flores à sua vinha nutritiva.", "Banhos preparados com as flores de sua", "vinha têm efeito relaxante e", "valem muito."],
    "sPokedexText_ORANGURU": ["No fundo da selva, no alto do dossel,", "vive este Pokemon. Em raras ocasiões,", "aparece na praia para medir", "astúcia com Slowking."],
    "sPokedexText_PASSIMIAN": ["Lutam usando BERRIES duras como armas.", "Formam grupos de cerca de 20", "indivíduos, unidos pelo", "trabalho em equipe."],
    "sPokedexText_WIMPOD": ["Este Pokemon é covarde. Quando dispara", "em fuga desesperada, o bater de suas", "muitas patas deixa o chão", "limpinho."],
    "sPokedexText_GOLISOPOD": ["Luta com habilidade usando os seis", "braços e o talho relampejante de suas", "garras gigantes e afiadas."],
    "sPokedexText_SANDYGAST": ["Controla quem põe a mão em sua boca,", "para aumentar o monte de areia do seu", "corpo. Este Pokemon encarna rancores", "dos que partiram."],
    "sPokedexText_PALOSSAND": ["Pessoas possuídas, controladas por", "este Pokemon, transformaram seu monte", "de areia num castelo. Ao evoluir,", "seu poder cresceu."],
    "sPokedexText_PYUKUMUKU": ["Vive em mares rasos, como as áreas", "perto da praia. O muco pegajoso que", "cobre seu corpo é usado para", "hidratar a pele."],
    "sPokedexText_TYPE_NULL": ["Pelo perigo de este Pokemon sintético", "sair de controle, ele usa uma máscara", "de contenção para restringir", "seu poder."],
    "sPokedexText_SILVALLY": ["Silvally vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_MINIOR": ["Minior vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_KOMALA": ["Nasce dormindo e morre dormindo. Todos", "os seus movimentos, ao que parece, não", "passam de reviradas", "no sono."],
    "sPokedexText_TURTONATOR": ["O casco de suas costas é quimicamente", "instável e explode com violência se", "golpeado. O buraco na barriga é", "seu ponto fraco."],
    "sPokedexText_TOGEDEMARU": ["Togedemaru vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_MIMIKYU": ["Mimikyu vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_BRUXISH": ["Atordoa a presa com poderes psíquicos", "e a tritura com os dentes fortes. Até", "a concha de Shellder vira", "farelo."],
    "sPokedexText_DRAMPA": ["Este Pokemon é amigável com pessoas e", "ama as crianças acima de tudo. Vem do", "fundo das montanhas para brincar", "com elas."],
    "sPokedexText_DHELMISE": ["A alma de algas à deriva nas ondas", "renasceu como este Pokemon. Ele se", "mantém com novas infusões", "de destroços."],
    "sPokedexText_JANGMO_O": ["Expressa seus sentimentos batendo nas", "próprias escamas. Sons metálicos ecoam", "pelas montanhas onde vive."],
    "sPokedexText_HAKAMO_O": ["Troca e regenera as escamas sem parar.", "Elas ficam mais duras a cada troca.", "Seus socos escamosos rasgam os", "rivais em pedaços."],
    "sPokedexText_KOMMO_O": ["Kommo-o vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_TAPU_KOKO": ["Confunde os inimigos voando rápido", "demais para os olhos acompanharem.", "Tem pavio curtíssimo, mas logo esquece", "por que se irritou."],
    "sPokedexText_TAPU_LELE": ["Um aroma fragrante de flores o segue.", "Ao esvoaçar, espalha escamas de brilho", "estranho. Tocá-las", "revigora."],
    "sPokedexText_TAPU_BULU": ["Faz a vegetação crescer e absorve a", "energia desse crescimento. Arranca", "árvores grandes pela raiz e as", "balança como clavas."],
    "sPokedexText_TAPU_FINI": ["Dizem que cria uma água pura capaz de", "lavar qualquer corrupção. A névoa", "densa que o envolve leva quem", "o perturba ao transe."],
    "sPokedexText_COSMOG": ["Em eras passadas, era chamado de filho", "das estrelas. Dizem que é um Pokemon", "de outro mundo. Junta poeira", "da atmosfera."],
    "sPokedexText_COSMOEM": ["Imóvel como se estivesse morto, seu", "corpo é levemente morno ao toque. Algo", "se acumula em torno de seu", "núcleo negro."],
    "sPokedexText_SOLGALEO": ["Dizem que vive em outro mundo. A luz", "intensa que irradia da superfície do", "corpo faz a noite mais escura virar", "pleno dia."],
    "sPokedexText_LUNALA": ["Quando seu terceiro olho desperta, ele", "voa para outro mundo. Este Pokemon", "devora luz, trazendo a escuridão", "sem lua."],
    "sPokedexText_NIHILEGO": ["Uma das misteriosas Ultracriaturas.", "Não se sabe ao certo se este Pokemon", "tem consciência própria."],
    "sPokedexText_BUZZWOLE": ["Esta forma de vida chamada", "Ultracriatura veio de outro mundo.", "Exibe o corpo, mas não se sabe se é", "orgulho ou ameaça."],
    "sPokedexText_PHEROMOSA": ["Uma das perigosas Ultracriaturas.", "Recusa-se a tocar qualquer coisa,", "talvez por sentir alguma impureza", "neste mundo."],
    "sPokedexText_XURKITREE": ["Uma das misteriosas formas de vida", "chamadas Ultracriaturas. Choques", "elétricos espantosos emanam de todo o", "seu corpo, dizem."],
    "sPokedexText_CELESTEELA": ["Surgiu da Ultrafenda. Uma das", "Ultracriaturas: testemunhas a viram", "cruzando o céu expelindo gás", "dos dois braços."],
    "sPokedexText_KARTANA": ["Esta Ultracriatura veio da Ultrafenda.", "Parece não atacar por conta própria,", "mas seu corpo afiado é perigoso", "só de tocar."],
    "sPokedexText_GUZZLORD": ["Uma Ultracriatura perigosa: já devorou", "montanhas e engoliu prédios inteiros,", "segundo relatos."],
    "sPokedexText_NECROZMA": ["Lembrando as Ultracriaturas, esta", "forma de vida, aparentemente adormecida", "no subsolo, teria vindo de", "outro mundo."],
    "sPokedexText_MAGEARNA": ["Este Pokemon artificial, construído há", "mais de 500 anos, entende a fala", "humana, mas não", "consegue falar."],
    "sPokedexText_MARSHADOW": ["Capaz de se ocultar na sombra dos", "outros, nunca aparece diante de", "humanos, e sua existência era", "tida como lenda."],
    "sPokedexText_POIPOLE": ["Esta Ultracriatura é querida o", "bastante para ser escolhida como", "primeiro parceiro em seu", "próprio mundo."],
    "sPokedexText_NAGANADEL": ["Guarda centenas de litros de líquido", "venenoso dentro do corpo. É uma das", "criaturas chamadas", "Ultracriaturas."],
    "sPokedexText_STAKATAKA": ["Surgiu de uma Ultrafenda. Cada um", "parece ser composto de muitas formas", "de vida empilhadas umas", "sobre as outras."],
    "sPokedexText_BLACEPHALON": ["Desliza até as pessoas e explode a", "própria cabeça sem aviso. É uma das", "Ultracriaturas."],
    "sPokedexText_ZERAORA": ["Aproxima-se dos inimigos na velocidade", "do relâmpago e os despedaça com", "suas garras afiadas."],
    "sPokedexText_MELTAN": ["Derrete partículas de ferro e outros", "metais do subsolo para absorvê-las", "pelo corpo líquido."],
    "sPokedexText_MELMETAL": ["Reverenciado há muito tempo pela", "capacidade de criar ferro do nada, por", "algum motivo voltou à vida após", "3.000 anos."],
    "sPokedexText_GROOKEY": ["Quando usa seu graveto especial para", "marcar um ritmo, as ondas sonoras", "levam energia revitalizante às", "plantas ao redor."],
    "sPokedexText_THWACKEY": ["Quanto mais rápido um Thwackey marca o", "ritmo com seus dois gravetos, mais", "respeito ganha entre", "os seus."],
    "sPokedexText_RILLABOOM": ["Tamborilando, acessa o poder de seu", "toco de árvore especial. As raízes do", "toco seguem sua direção", "na batalha."],
    "sPokedexText_SCORBUNNY": ["Um aquecimento de corrida faz a", "energia de fogo correr pelo corpo", "deste Pokemon. Aí ele está pronto para", "lutar com tudo."],
    "sPokedexText_RABOOT": ["Seu pelo grosso e fofo o protege do", "frio e permite usar golpes de fogo", "ainda mais quentes."],
    "sPokedexText_CINDERACE": ["Embaixadinha vai, embaixadinha vem: a", "pedrinha vira uma bola de futebol em", "chamas. Seus chutes atingem forte e", "deixam tudo chamuscado."],
    "sPokedexText_SOBBLE": ["Com medo, este Pokemon chora. Suas", "lágrimas têm o ardor químico de 100", "cebolas, e os agressores não conseguem", "abrir os olhos."],
    "sPokedexText_DRIZZILE": ["Combatente esperto, este Pokemon luta", "usando balões d'água criados com a", "umidade secretada pelas palmas", "das mãos."],
    "sPokedexText_INTELEON": ["Tem muitas capacidades ocultas, como", "dedos que disparam água e uma membrana", "nas costas usada para", "planar."],
    "sPokedexText_SKWOVET": ["Encontrado por toda a região de Galar,", "este Pokemon fica inquieto se as", "bochechas não estão cheias", "de BERRIES."],
    "sPokedexText_GREEDENT": ["Guarda BERRIES na cauda, tantas que", "vivem caindo. Mas este Pokemon é meio", "lento e nem percebe", "a perda."],
    "sPokedexText_ROOKIDEE": ["Desafia com bravura qualquer oponente,", "por mais poderoso. Este Pokemon", "aprende com cada batalha, mesmo", "nas derrotas."],
    "sPokedexText_CORVISQUIRE": ["Espertos o bastante para usar", "ferramentas em batalha, já foram", "vistos atirando pedras e usando", "cordas contra rivais."],
    "sPokedexText_CORVIKNIGHT": ["Este Pokemon reina supremo nos céus da", "região de Galar. O lustre negro de", "suas asas intimida qualquer", "desafiante."],
    "sPokedexText_BLIPBUG": ["Coletor constante de informações, este", "Pokemon é muito inteligente.", "Muito forte é o que", "ele não é."],
    "sPokedexText_DOTTLER": ["Mal se move, mas está vivo. Esconder-se", "na casca sem comida nem água parece", "ter despertado seus poderes", "psíquicos."],
    "sPokedexText_ORBEETLE": ["É famoso pelo alto nível de", "inteligência, e o tamanho do cérebro", "prova que também possui um vasto", "poder psíquico."],
    "sPokedexText_NICKIT": ["Com a ajuda das almofadas macias das", "patas, saqueia em silêncio os estoques", "de comida de outros Pokemon.", "Vive do que rouba."],
    "sPokedexText_THIEVUL": ["Marca em segredo os alvos com um", "cheiro. Seguindo o rastro, espreita os", "alvos e rouba deles quando", "estão desatentos."],
    "sPokedexText_GOSSIFLEUR": ["Fixa-se no chão com sua única perna e", "toma sol. Depois do banho de sol, suas", "pétalas ganham cores", "vivas."],
    "sPokedexText_ELDEGOSS": ["As sementes presas à sua pluma de", "algodão são cheias de nutrientes. Ele", "as espalha ao vento para nutrir", "plantas e Pokemon."],
    "sPokedexText_WOOLOO": ["Sua lã encaracolada amortece tão bem", "que este Pokemon pode cair de um", "penhasco e sair andando como se", "nada fosse."],
    "sPokedexText_DUBWOOL": ["Teça um tapete com sua lã elástica e", "você terá algo mais próximo de uma", "cama elástica. Vai quicar", "sem querer."],
    "sPokedexText_CHEWTLE": ["Ao que parece, a coceira dos dentes", "nascendo o impele a abocanhar", "qualquer coisa à sua frente."],
    "sPokedexText_DREDNAW": ["Com mandíbulas que cortam barras de", "aço, este Pokemon agressivo abocanha", "sua presa azarada."],
    "sPokedexText_YAMPER": ["Este Pokemon é muito popular como cão", "pastor na região de Galar. Ao correr,", "gera eletricidade a partir da base", "de sua cauda."],
    "sPokedexText_BOLTUND": ["Este Pokemon gera eletricidade e a", "canaliza para as pernas para mantê-las", "firmes. Boltund corre sem parar por", "três dias inteiros."],
    "sPokedexText_ROLYCOLY": ["A maior parte do corpo tem a mesma", "composição do carvão. A propósito,", "este Pokemon foi descoberto em minas", "de carvão."],
    "sPokedexText_CARKOL": ["Forma carvão dentro do corpo. O carvão", "que este Pokemon deixava cair ajudou a", "abastecer a vida do povo", "de Galar."],
    "sPokedexText_COALOSSAL": ["Costuma ser pacífico, mas o vandalismo", "nas minas o enfurece. Os infratores", "são incinerados com chamas de", "1.500 graus."],
    "sPokedexText_APPLIN": ["Passa a vida inteira dentro de uma", "maçã. Esconde-se dos inimigos", "naturais, os Pokemon pássaros,", "fingindo ser só uma maçã."],
    "sPokedexText_FLAPPLE": ["Comeu uma maçã azeda, e isso induziu", "sua evolução. Nas bochechas, guarda um", "ácido que causa", "queimaduras."],
    "sPokedexText_APPLETUN": ["Comer uma maçã doce causou sua", "evolução. Um aroma de néctar emana de", "seu corpo, atraindo os Pokemon", "insetos que ele caça."],
    "sPokedexText_SILICOBRA": ["Enquanto cava, engole areia e a guarda", "na bolsa do pescoço. A bolsa comporta", "mais de 8 kg de areia."],
    "sPokedexText_SANDACONDA": ["Quando contrai o corpo, mais de 100 kg", "de areia jorram de seu nariz. Se a", "areia acaba, ele fica", "abatido."],
    "sPokedexText_CRAMORANT": ["É tão forte que nocauteia alguns", "oponentes num só golpe, mas também", "pode esquecer quem estava", "enfrentando."],
    "sPokedexText_ARROKUDA": ["Se vê qualquer movimento ao redor,", "este Pokemon investe na hora, liderado", "por sua mandíbula pontiaguda", "como lança."],
    "sPokedexText_BARRASKEWDA": ["Este Pokemon tem mandíbula afiada como", "lança e forte como aço. Dizem que a", "carne de Barraskewda é saborosa de", "surpreender."],
    "sPokedexText_TOXEL": ["Guarda veneno numa bolsa interna e o", "secreta pela pele. Se você tocar neste", "Pokemon, um formigamento elétrico", "toma o corpo."],
    "sPokedexText_TOXTRICITY": ["Quando este Pokemon soa como se", "dedilhasse uma guitarra, na verdade", "arranha as saliências do peito para", "gerar eletricidade."],
    "sPokedexText_SIZZLIPEDE": ["Guarda gás inflamável no corpo e o usa", "para gerar calor. As seções amarelas", "da barriga ficam especialmente", "quentes."],
    "sPokedexText_CENTISKORCH": ["Quando esquenta, sua temperatura chega", "a cerca de 800 graus. Chicoteia o", "corpo e ataca com calor", "abrasador."],
    "sPokedexText_CLOBBOPUS": ["É muito curioso, mas seu jeito de", "investigar as coisas é tentar", "socá-las com os tentáculos. A busca", "deixa tudo em pedaços."],
    "sPokedexText_GRAPPLOCT": ["Um corpo feito só de músculos torna", "formidáveis os golpes de luta agarrada", "que este Pokemon executa."],
    "sPokedexText_SINISTEA": ["Dizem que este Pokemon nasceu quando", "um espírito solitário possuiu uma", "xícara de chá frio esquecida."],
    "sPokedexText_POLTEAGEIST": ["Esta espécie vive em bules antigos.", "A maioria dos bules é falsificada,", "mas, em raras ocasiões, acha-se uma", "peça autêntica."],
    "sPokedexText_HATENNA": ["Pela protuberância da cabeça, sente as", "emoções das outras criaturas. Se você", "não tem emoções, ele nunca", "se aproxima."],
    "sPokedexText_HATTREM": ["Não importa quem seja: aproxime", "emoções fortes deste Pokemon e ele vai", "silenciá-lo à força, com surras", "de suas tranças."],
    "sPokedexText_HATTERENE": ["Emite poder psíquico forte o bastante", "para causar dores de cabeça, como", "aviso para ninguém", "se aproximar."],
    "sPokedexText_IMPIDIMP": ["Pelo nariz, suga as emanações que", "pessoas e Pokemon produzem quando", "irritados. Nutre-se dessa energia", "negativa."],
    "sPokedexText_MORGREM": ["Quando fica de quatro como se pedisse", "perdão, está tentando atrair o", "desatento para atacar com o", "cabelo-lança."],
    "sPokedexText_GRIMMSNARL": ["Com o cabelo enrolado no corpo", "reforçando seus músculos, este Pokemon", "supera até mesmo Machamp."],
    "sPokedexText_OBSTAGOON": ["Sua voz tem volume de assustar.", "Obstagoon costuma assumir postura", "ameaçadora e gritar: o golpe se", "chama Obstruct."],
    "sPokedexText_PERRSERKER": ["O que parece um elmo de ferro é, na", "verdade, cabelo endurecido. Este", "Pokemon vive pela emoção", "da batalha."],
    "sPokedexText_CURSOLA": ["Sua concha transborda de energia", "sobrenatural ampliada. O ectoplasma", "serve de proteção para seu", "núcleo espiritual."],
    "sPokedexText_SIRFETCHD": ["Só Farfetch'd que sobreviveram a", "muitas batalhas alcançam esta", "evolução. Quando seu alho-poró murcha,", "ele se aposenta."],
    "sPokedexText_MR_RIME": ["É altamente habilidoso no sapateado.", "Balança sua bengala de gelo no", "compasso de seus movimentos", "graciosos."],
    "sPokedexText_RUNERIGUS": ["Uma maldição poderosa foi tecida numa", "pintura antiga. Após absorver o", "espírito de um Yamask, a pintura", "ganhou vida."],
    "sPokedexText_MILCERY": ["Este Pokemon nasceu de partículas de", "cheiro doce no ar. Seu corpo é", "feito de creme."],
    "sPokedexText_ALCREMIE": ["Lança enxames de mísseis, cada um", "feito de creme e carregado com", "100.000 quilocalorias. Quem é atingido", "perde o foco."],
    "sPokedexText_FALINKS": ["Cinco deles são soldados, e um é o", "comandante. As ordens do comandante", "são absolutas."],
    "sPokedexText_PINCURCHIN": ["Alimenta-se de algas, raspando-as das", "rochas com os dentes. Corrente", "elétrica flui das pontas de seus", "espinhos."],
    "sPokedexText_SNOM": ["Cospe fios imbuídos de uma energia", "gélida e os usa para prender o corpo", "aos galhos, disfarçado de", "pingente de gelo."],
    "sPokedexText_FROSMOTH": ["Escamas geladas caem de suas asas como", "neve enquanto voa por campos e montes.", "A temperatura das asas é menor que", "180 graus negativos."],
    "sPokedexText_STONJOURNER": ["Fica parado nos campos, vendo o sol", "descer do zênite ao horizonte. Este", "Pokemon tem talento para chutes", "poderosos."],
    "sPokedexText_EISCUE": ["Veio à deriva nas correntes do oceano,", "de um lugar glacial. Mantém a cabeça", "sempre congelada para ficar", "bem fria."],
    "sPokedexText_INDEEDEE": ["Servem com dedicação a pessoas e", "Pokemon para colher sentimentos de", "gratidão. As fêmeas são ótimas", "babás."],
    "sPokedexText_MORPEKO": ["A fome intensa o leva a extremos de", "violência, e a eletricidade de suas", "bochechas se converteu em energia", "do tipo Sombrio."],
    "sPokedexText_CUFANT": ["Escava o chão com a tromba. Também é", "muito forte: carrega mais de cinco", "toneladas sem qualquer sinal", "de esforço."],
    "sPokedexText_COPPERAJAH": ["Vieram de outra região há muito tempo", "e trabalharam junto com os humanos.", "Sua pele verde resiste", "à água."],
    "sPokedexText_DRACOZOLT": ["Nos tempos antigos, era imbatível", "graças à parte inferior poderosa, mas", "foi extinto ao comer todas", "as plantas."],
    "sPokedexText_ARCTOZOLT": ["O tremor de sua metade superior", "congelante é o que gera sua", "eletricidade. Tem muita dificuldade", "para andar."],
    "sPokedexText_DRACOVISH": ["Pernas e mandíbulas poderosas fizeram", "dele o predador máximo de sua era.", "Sua própria caça excessiva", "o extinguiu."],
    "sPokedexText_ARCTOVISH": ["Embora capture presas congelando o", "ambiente, tem dificuldade para", "comê-las depois, pois sua boca fica", "no topo da cabeça."],
    "sPokedexText_DURALUDON": ["Seu corpo lembra metal polido, sendo", "leve e forte ao mesmo tempo. O único", "defeito é que enferruja", "com facilidade."],
    "sPokedexText_DREEPY": ["Depois de renascer como Pokemon", "fantasma, Dreepy vagueia pelas áreas", "onde vivia quando era vivo, nos", "mares pré-históricos."],
    "sPokedexText_DRAKLOAK": ["Voa a mais de 190 km/h. Luta ao lado", "dos Dreepy e cuida deles até que", "consigam evoluir."],
    "sPokedexText_DRAGAPULT": ["Quando não está lutando, guarda Dreepy", "nos buracos de seus chifres. Na", "batalha, ele os dispara em velocidade", "supersônica."],
    "sPokedexText_ZACIAN": ["Conhecido como herói lendário, este", "Pokemon absorve partículas de metal e", "as transforma na arma com", "que luta."],
    "sPokedexText_ZAMAZENTA": ["No passado, trabalhou junto com um rei", "do povo para salvar a região de Galar.", "Absorve metal e o usa", "em batalha."],
    "sPokedexText_ETERNATUS": ["O núcleo em seu peito absorve a", "energia que emana das terras de Galar.", "Essa energia é o que mantém", "Eternatus ativo."],
    "sPokedexText_KUBFU": ["Kubfu treina duro para aperfeiçoar", "seus golpes. Os golpes que dominar", "determinarão qual forma ele", "assumirá."],
    "sPokedexText_URSHIFU": ["Esta forma de Urshifu acredita", "piamente em vencer com uma chuva de", "golpes. Seus ataques fluem sem parar,", "como um rio."],
    "sPokedexText_ZARUDE": ["Nas florestas densas, este Pokemon", "vive em bando com outros da espécie.", "É muito territorial e", "feroz."],
    "sPokedexText_REGIELEKI": ["Este Pokemon é um aglomerado de", "energia elétrica. Dizem que remover os", "anéis de seu corpo libera seu", "poder total."],
    "sPokedexText_REGIDRAGO": ["Uma teoria acadêmica propõe que os", "braços de Regidrago já foram a cabeça", "de um antigo Pokemon dragão."],
    "sPokedexText_GLASTRIER": ["Glastrier emite frio intenso pelos", "cascos. Também é um Pokemon briguento:", "tudo o que quer, toma", "à força."],
    "sPokedexText_SPECTRIER": ["Sonda o ambiente com todos os sentidos", "menos um: não usa a visão. Seus", "coices separam alma", "e corpo."],
    "sPokedexText_CALYREX": ["Calyrex é um Pokemon piedoso, capaz de", "conceder cura e bênçãos. Reinou sobre", "Galar em tempos antigos."],
    "sPokedexText_WYRDEER": ["As esferas negras brilham com uma luz", "sobrenatural quando ele ergue", "barreiras invisíveis."],
    "sPokedexText_KLEAVOR": ["Uma criatura violenta que derruba", "árvores com seus machados rústicos e", "se escuda com rocha dura."],
    "sPokedexText_URSALUNA": ["O terreno pantanoso deu a Ursaluna seu", "físico troncudo e a nova capacidade de", "manipular turfa à vontade."],
    "sPokedexText_BASCULEGION": ["As almas de seus companheiros envolvem", "seu corpo e o impulsionam sem esforço", "até pelas corredeiras mais", "bravas."],
    "sPokedexText_SNEASLER": ["Por seu veneno perverso e seu vigor", "físico intimidador, nenhuma outra", "espécie consegue competir", "com ele."],
    "sPokedexText_OVERQWIL": ["Seus espinhos de lança e o gênio", "selvagem renderam-lhe o apelido de", "“Demônio do Mar”. Sorve veneno", "para se nutrir."],
    "sPokedexText_ENAMORUS": ["Das nuvens, desce sobre aqueles que", "tratam qualquer forma de vida com", "desrespeito e aplica um castigo", "colérico e impiedoso."],
    "sPokedexText_SPRIGATITO": ["O aroma doce que seu corpo exala", "hipnotiza quem está por perto. O", "cheiro fica mais forte quando este", "Pokemon toma sol."],
    "sPokedexText_FLORAGATO": ["Floragato maneja com destreza a vinha", "escondida sob o pelo longo, golpeando", "os oponentes com o botão", "de flor duro."],
    "sPokedexText_MEOWSCARADA": ["Este Pokemon usa o pelo refletivo de", "sua capa para camuflar o caule de sua", "flor, criando a ilusão de que a", "flor flutua."],
    "sPokedexText_FUECOCO": ["Sua bolsa de fogo é pequena, então a", "energia vive vazando. Ela é liberada", "pela cavidade no topo da cabeça de", "Fuecoco e tremula."],
    "sPokedexText_CROCALOR": ["A combinação da energia de fogo de", "Crocalor com sua vitalidade", "transbordante criou uma bola de fogo", "em forma de ovo na cabeça."],
    "sPokedexText_SKELEDIRGE": ["O canto suave de Skeledirge acalma a", "alma de todos que o ouvem. Ele torra", "os inimigos com chamas de mais", "de 3.000 graus."],
    "sPokedexText_QUAXLY": ["Suas pernas fortes o deixam nadar com", "facilidade até em rios de correnteza.", "Gosta de tudo arrumado e tende a", "pensar demais."],
    "sPokedexText_QUAXWELL": ["O esforçado Quaxwell observa pessoas e", "Pokemon de várias regiões e incorpora", "os movimentos deles às suas", "rotinas de dança."],
    "sPokedexText_QUAQUAVAL": ["Um só chute de Quaquaval manda um", "caminhão capotando. Este Pokemon usa", "as pernas poderosas em danças", "de terras distantes."],
    "sPokedexText_LECHONK": ["Procura comida o dia todo. Possui um", "olfato aguçado, mas não o usa para", "nada além de buscar", "alimento."],
    "sPokedexText_OINKOLOGNE": ["É um Pokemon meticuloso que gosta de", "tudo arrumado. Envolve-se num aroma", "floral que acalma os Pokemon", "ao seu redor."],
    "sPokedexText_TAROUNTULA": ["O fio que secreta pelo traseiro é", "forte como arame. O segredo dessa", "resistência ainda é tema", "de pesquisas."],
    "sPokedexText_SPIDOPS": ["Prende-se a galhos e tetos com seus", "fios e se move sem fazer barulho.", "Elimina a presa antes mesmo de", "ser notado."],
    "sPokedexText_NYMBLE": ["Mantém o terceiro par de pernas", "dobrado. Em apuros, este Pokemon salta", "mais de 9 metros com a força", "dessas pernas."],
    "sPokedexText_LOKIX": ["Quando decide lutar com tudo, apoia-se", "nas pernas antes dobradas e entra no", "Modo Confronto. Neutraliza os inimigos", "em pouco tempo."],
    "sPokedexText_PAWMI": ["As almofadas das patas são órgãos que", "descarregam eletricidade. Pawmi atira", "choques pelas patas dianteiras,", "meio desequilibrado."],
    "sPokedexText_PAWMO": ["Quando o grupo é atacado, Pawmo é o", "primeiro a saltar para a batalha,", "vencendo com uma técnica de luta", "que usa eletricidade."],
    "sPokedexText_PAWMOT": ["Este Pokemon costuma reagir devagar,", "mas, ao entrar em batalha, derruba os", "inimigos com movimentos velozes", "como relâmpagos."],
    "sPokedexText_TANDEMAUS": ["Num grande trabalho de equipe, usam os", "incisivos para cortar pedaços de", "qualquer material útil para o ninho", "e fogem com eles."],
    "sPokedexText_MAUSHOLD": ["O par maior protege os pequenos nas", "batalhas. Diante de oponentes fortes,", "o grupo todo entra", "na luta."],
    "sPokedexText_FIDOUGH": ["Este Pokemon é liso e úmido ao toque.", "O fermento no hálito de Fidough induz", "fermentação nas", "redondezas."],
    "sPokedexText_DACHSBUN": ["O aroma agradável que emana do corpo", "deste Pokemon ajuda o trigo a crescer,", "por isso Dachsbun é um tesouro das", "vilas rurais."],
    "sPokedexText_SMOLIV": ["Este Pokemon converte nutrientes em", "óleo, que guarda na fruta de sua", "cabeça. Passa fácil uma semana sem", "comer nem beber."],
    "sPokedexText_DOLLIV": ["Dolliv divide com os outros seu óleo", "saboroso de aroma fresco. Esta espécie", "convive com os humanos desde", "tempos remotos."],
    "sPokedexText_ARBOLIVA": ["Este Pokemon repele inimigos lançando", "seu óleo rico e aromático com força", "suficiente para partir um", "pedregulho."],
    "sPokedexText_SQUAWKABILLY": ["Seus maiores bandos passam de 50", "indivíduos. Voam por cidades e", "florestas atrás de comida, fazendo", "uma barulheira."],
    "sPokedexText_NACLI": ["O chão raspa seu corpo conforme", "viaja, deixando sal para trás. Sal é", "criado sem parar dentro", "do seu corpo."],
    "sPokedexText_NACLSTACK": ["Comprime sal-gema dentro do corpo e", "dispara projéteis de sal endurecido", "com força para perfurar uma", "chapa de ferro."],
    "sPokedexText_GARGANACL": ["Garganacl esfrega as pontas dos dedos", "e polvilha sal sobre Pokemon feridos.", "Até ferimentos graves saram", "com isso."],
    "sPokedexText_CHARCADET": ["Carvão queimado ganhou vida e virou", "Pokemon. Com espírito de luta ardente,", "Charcadet enfrenta até oponentes", "muito fortes."],
    "sPokedexText_ARMAROUGE": ["Armarouge evoluiu com o uso de uma", "armadura que pertenceu a um guerreiro", "ilustre. Este Pokemon é incrivelmente", "leal."],
    "sPokedexText_CERULEDGE": ["As lâminas de fogo de seus braços", "ardem com o rancor de um espadachim", "que tombou antes de cumprir", "seu objetivo."],
    "sPokedexText_TADBULB": ["Tadbulb balança a cauda para gerar", "eletricidade. Se sente perigo, faz a", "cabeça piscar para alertar os", "companheiros."],
    "sPokedexText_BELLIBOLT": ["Quando este Pokemon expande e contrai", "o corpo balofo, o dínamo em forma de", "umbigo na barriga produz muita", "eletricidade."],
    "sPokedexText_WATTREL": ["Quando suas asas pegam o vento, os", "ossos dentro delas produzem", "eletricidade. Mergulha no oceano e", "eletrocuta as presas."],
    "sPokedexText_KILOWATTREL": ["Usa o saco da garganta para guardar a", "eletricidade gerada pelas asas. Quase", "não há óleo em suas penas, então", "ele voa leve."],
    "sPokedexText_MASCHIFF": ["Sua mandíbula bem desenvolvida e as", "presas trituram pedregulhos, e sua", "gordura espessa é uma excelente", "defesa."],
    "sPokedexText_MABOSSTIFF": ["Mabosstiff adora brincar com", "crianças. Costuma ser dócil, mas ganha", "um ar intimidador ao proteger", "sua família."],
    "sPokedexText_SHROODLE": ["Para manter inimigos longe de seu", "território, pinta marcas ao redor do", "ninho com um líquido venenoso de", "odor acre."],
    "sPokedexText_GRAFAIAI": ["Cada Grafaiai pinta seu próprio", "padrão individual, e repete esse mesmo", "padrão a vida toda, por", "onde passa."],
    "sPokedexText_BRAMBLIN": ["Uma alma que não pôde seguir adiante", "foi soprada pelo vento até se enredar", "em capim seco e virar", "um Pokemon."],
    "sPokedexText_BRAMBLEGHAST": ["Abre os galhos da cabeça para envolver", "a presa. Depois de absorver toda a", "energia vital de que precisa,", "descarta o resto."],
    "sPokedexText_TOEDSCOOL": ["Embora pareça Tentacool, Toedscool é", "uma espécie totalmente diferente. Suas", "pernas são finas, mas correm", "a 50 km/h."],
    "sPokedexText_TOEDSCRUEL": ["Estes Pokemon se reúnem em grupos e", "formam colônias no fundo das", "florestas. Odeiam quando estranhos", "se aproximam."],
    "sPokedexText_KLAWF": ["Klawf fica pendurado de cabeça para", "baixo nos penhascos, esperando presas.", "Mas não aguenta muito tempo: o", "sangue sobe à cabeça."],
    "sPokedexText_CAPSAKID": ["Quanto mais sol este Pokemon toma,", "mais substâncias picantes seu corpo", "produz, e mais apimentado", "ele fica."],
    "sPokedexText_SCOVILLAIN": ["A cabeça verde ficou cruel por causa", "das substâncias picantes que estimulam", "seu cérebro. Quando surta,", "ninguém segura."],
    "sPokedexText_RELLOR": ["Este Pokemon cria uma bola de lama", "misturando areia e terra com energia", "psíquica. Preza a bola mais que a", "própria vida."],
    "sPokedexText_RABSCA": ["O corpo que sustenta a bola mal se", "move. Por isso, pensa-se que o corpo", "verdadeiro deste Pokemon está, na", "verdade, dentro dela."],
    "sPokedexText_FLITTLE": ["Os dedos de Flittle levitam a cerca de", "um centímetro do chão, graças ao poder", "psíquico emitido pelos babados de", "sua barriga."],
    "sPokedexText_ESPATHRA": ["Imobiliza oponentes banhando-os no", "poder psíquico de seus olhos grandes.", "Apesar da aparência, tem um", "gênio cruel."],
    "sPokedexText_TINKATINK": ["Este Pokemon martela sucata de ferro", "para forjar um martelo. Refaz o", "martelo de novo e de novo até", "ficar satisfeito."],
    "sPokedexText_TINKATUFF": ["Estes Pokemon moram em pilhas de", "sucata. Testam a resistência dos", "martelos uns dos outros batendo-os", "entre si."],
    "sPokedexText_TINKATON": ["O martelo passa de 100 kg, mas", "Tinkaton o balança com facilidade", "enquanto rouba o que bem", "entende."],
    "sPokedexText_WIGLETT": ["Este Pokemon capta o cheiro de um", "Veluza a mais de 20 metros e se", "esconde na areia."],
    "sPokedexText_WUGTRIO": ["Uma variedade de Pokemon peixe,", "Wugtrio já foi considerado uma forma", "regional de Dugtrio."],
    "sPokedexText_BOMBIRDIER": ["Bombirdier usa o avental do peito para", "embrulhar comida e levá-la ao ninho.", "Diverte-se soltando coisas que fazem", "barulhos altos."],
    "sPokedexText_FINIZEN": ["Seu anel d'água é feito de água do mar", "misturada a um fluido pegajoso que", "Finizen secreta pelo", "orifício nasal."],
    "sPokedexText_PALAFIN": ["Os genes ancestrais deste Pokemon", "despertaram. Agora é tão forte que", "levanta fácil um navio de cruzeiro", "com uma nadadeira."],
    "sPokedexText_VAROOM": ["A seção de aço é o corpo real de", "Varoom. Este Pokemon se prende a", "rochas e converte seus minerais em", "energia para viver."],
    "sPokedexText_REVAVROOM": ["Cria um gás a partir de veneno e", "minerais das rochas. Então detona o", "gás em seus cilindros, agora oito,", "para gerar energia."],
    "sPokedexText_CYCLIZAR": ["Corre a mais de 110 km/h carregando um", "humano. O calor do corpo de quem monta", "aquece as costas de Cyclizar e eleva", "seu ânimo."],
    "sPokedexText_ORTHWORM": ["Quando atacado, este Pokemon empunha", "os tentáculos do corpo como punhos e", "cobre o oponente com uma tempestade", "de socos."],
    "sPokedexText_GLIMMET": ["Os cristais minerais tóxicos de", "Glimmet parecem pétalas de flor. Este", "Pokemon espalha pó venenoso como", "pólen para se proteger."],
    "sPokedexText_GLIMMORA": ["As pétalas de Glimmora são feitas de", "energia venenosa cristalizada.", "Descobriu-se há pouco que elas lembram", "Joias Tera."],
    "sPokedexText_GREAVARD": ["Este Pokemon amigável não gosta de", "ficar sozinho. Dê a ele a menor", "atenção e ele o seguirá por", "toda parte."],
    "sPokedexText_HOUNDSTONE": ["Houndstone passa a maior parte do", "tempo dormindo em cemitérios. Entre os", "Pokemon cães, é o mais leal", "ao seu dono."],
    "sPokedexText_FLAMIGO": ["Graças a um comportamento chamado", "“sincronização”, um bando inteiro", "destes Pokemon ataca ao mesmo tempo,", "em perfeita harmonia."],
    "sPokedexText_CETODDLE": ["Esta espécie deixou o oceano e passou", "a viver em terra há muitíssimo tempo.", "Parece ser parente próxima", "de Wailmer."],
    "sPokedexText_CETITAN": ["Energia de gelo se acumula no chifre", "da mandíbula superior, levando-o a", "temperaturas criogênicas que congelam", "os arredores."],
    "sPokedexText_VELUZA": ["Veluza tem excelente capacidade de", "regeneração. Descarta carne", "sobressalente do corpo para ganhar", "agilidade e então ataca."],
    "sPokedexText_DONDOZO": ["Trata Tatsugiri como seu chefe e o", "segue com lealdade. Embora poderoso,", "Dondozo aparentemente não é", "muito esperto."],
    "sPokedexText_TATSUGIRI": ["É um pequeno Pokemon dragão. Vive", "dentro da boca de Dondozo para se", "proteger dos inimigos", "do lado de fora."],
    "sPokedexText_ANNIHILAPE": ["Quando sua raiva passou de um ponto", "crítico, este Pokemon ganhou um poder", "que não se prende aos limites", "do corpo."],
    "sPokedexText_CLODSIRE": ["Quando atacado, este Pokemon revida", "projetando espinhos grossos do corpo.", "É um movimento arriscado que", "aposta tudo."],
    "sPokedexText_FARIGIRAF": ["Agora que as ondas cerebrais da cabeça", "e da cauda estão sincronizadas, o", "poder psíquico deste Pokemon é 10", "vezes o de Girafarig."],
    "sPokedexText_DUDUNSPARCE": ["Este Pokemon usa a cauda dura para", "fazer o ninho, perfurando a rocha no", "subsolo profundo. O ninho pode passar", "de 10 km de extensão."],
    "sPokedexText_KINGAMBIT": ["Embora comande um exército imenso em", "batalha, não é bom em bolar", "estratégias complexas. Vence na", "força bruta."],
    "sPokedexText_GREAT_TUSK": ["Avistamentos deste Pokemon ocorreram", "nos últimos anos. O nome Great Tusk", "veio de uma criatura listada em", "certo livro."],
    "sPokedexText_SCREAM_TAIL": ["Há só um avistamento registrado deste", "Pokemon. Ele lembra uma criatura", "misteriosa retratada numa", "revista paranormal."],
    "sPokedexText_BRUTE_BONNET": ["Lembra um pouco um Pokemon descrito", "numa revista duvidosa como um", "cruzamento de dinossauro com", "cogumelo."],
    "sPokedexText_FLUTTER_MANE": ["Tem traços parecidos com um", "pterossauro fantasmagórico mostrado", "numa revista paranormal, mas as", "diferenças são muitas."],
    "sPokedexText_SLITHER_WING": ["Este Pokemon misterioso tem algumas", "semelhanças com uma criatura que um", "livro antigo apresentou como", "Slither Wing."],
    "sPokedexText_SANDY_SHOCKS": ["Lembra levemente um Magneton que teria", "vivido 10.000 anos, destaque de um", "artigo numa revista", "paranormal."],
    "sPokedexText_IRON_TREADS": ["Avistamentos deste Pokemon ocorreram", "nos últimos anos. Ele lembra um objeto", "misterioso descrito num velho diário", "de expedição."],
    "sPokedexText_IRON_BUNDLE": ["Sua forma lembra um robô mostrado num", "artigo de revista paranormal. Dizem", "que o robô foi criado por uma", "civilização antiga."],
    "sPokedexText_IRON_HANDS": ["É muito parecido com um ciborgue", "coberto com exclusividade por uma", "revista paranormal. O ciborgue seria", "um atleta renascido."],
    "sPokedexText_IRON_JUGULIS": ["Lembra certo Pokemon apresentado numa", "revista paranormal, descrito como cria", "de um Hydreigon apaixonado por", "um robô."],
    "sPokedexText_IRON_MOTH": ["Não há registros de captura desta", "espécie. Faltam dados, mas seus traços", "batem com um objeto descrito num", "livro antigo."],
    "sPokedexText_IRON_THORNS": ["Tem semelhanças com um Pokemon", "apresentado numa revista duvidosa como", "um Tyranitar de um bilhão de anos", "no futuro."],
    "sPokedexText_FRIGIBAX": ["Este Pokemon vive em florestas e áreas", "rochosas. Com o poder da nadadeira", "dorsal, refrigera o interior do ninho", "como uma geladeira."],
    "sPokedexText_ARCTIBAX": ["Arctibax congela o ar ao redor,", "protegendo o rosto com uma máscara de", "gelo e tornando a nadadeira dorsal uma", "lâmina de gelo."],
    "sPokedexText_BAXCALIBUR": ["Lança-se à batalha de cabeça para", "baixo, expelindo ar gélido pela boca.", "Finaliza os oponentes com sua", "lâmina dorsal."],
    "sPokedexText_GIMMIGHOUL": ["Vive dentro de um baú de tesouro", "antigo. Às vezes é esquecido em cantos", "de loja, pois ninguém percebe que é", "um Pokemon."],
    "sPokedexText_GHOLDENGO": ["Tem um corpo robusto feito de moedas", "empilhadas. Gholdengo esmaga os", "inimigos disparando moeda atrás de", "moeda, sem parar."],
    "sPokedexText_WO_CHIEN": ["O rancor de alguém punido por", "escrever em tábuas de madeira os males", "do rei vestiu-se de folhas mortas e", "virou um Pokemon."],
    "sPokedexText_CHIEN_PAO": ["Este Pokemon controla 100 toneladas de", "neve caída. Brinca inocente, saltando", "para dentro e fora das avalanches", "que causa."],
    "sPokedexText_TING_LU": ["Baixa lentamente sua cabeça pesadíssima", "ao chão, rachando a terra com fendas", "enormes de mais de 50 metros de", "profundidade."],
    "sPokedexText_CHI_YU": ["Controla chamas que ardem a mais de", "3.000 graus. Nada tranquilamente pelo", "mar de lava que cria ao derreter", "rocha e areia."],
    "sPokedexText_ROARING_MOON": ["Segundo um artigo de uma revista", "duvidosa, este Pokemon tem alguma", "ligação com a Megaevolução."],
    "sPokedexText_IRON_VALIANT": ["Tem semelhanças com a invenção de um", "cientista louco coberta por uma", "revista paranormal."],
    "sPokedexText_KORAIDON": ["Este Pokemon lembra Cyclizar, mas é", "bem mais troncudo e feroz. Nada se", "sabe sobre sua ecologia ou outras", "características."],
    "sPokedexText_MIRAIDON": ["Parece ser a Serpente de Ferro", "mencionada num Livro Violeta. Dizem", "que ela transformou a terra em", "cinzas num instante."],
    "sPokedexText_WALKING_WAKE": ["Esta criatura feroz é envolta em", "mistério. Seu nome vem de um monstro", "aquático citado num diário antigo."],
    "sPokedexText_IRON_LEAVES": ["Segundo os poucos relatos de", "testemunhas, usou suas lâminas", "brilhantes para fatiar árvores", "grandes e pedregulhos."],
    "sPokedexText_DIPPLIN": ["Dipplin são duas criaturas num só", "Pokemon. Sua evolução foi provocada", "por uma maçã especial de", "certa região."],
    "sPokedexText_POLTCHAGEIST": ["Instalou-se num pote de chá caríssimo.", "É preciso um especialista para", "distinguir os potes caros", "dos baratos."],
    "sPokedexText_SINISTCHA": ["Quanto mais mexe com o batedor de chá", "em sua cabeça, mais energia acumula.", "Faz isso para se preparar", "para a batalha."],
    "sPokedexText_OKIDOGI": ["Depois de ter os músculos estimulados", "pela corrente tóxica do pescoço,", "Okidogi se transformou e ganhou um", "físico poderoso."],
    "sPokedexText_MUNKIDORI": ["A corrente é feita de toxinas que", "ampliam capacidades. Ela estimulou o", "cérebro de Munkidori e fez florescer", "seus poderes psíquicos."],
    "sPokedexText_FEZANDIPITI": ["Fezandipiti deve sua beleza e sua voz", "adorável aos estimulantes tóxicos que", "emanam da corrente enrolada em", "seu corpo."],
    "sPokedexText_OGERPON": ["Ogerpon vive numa região distante.", "Sua ecologia ainda está", "sendo estudada."],
    "sPokedexText_ARCHALUDON": ["Acumula eletricidade estática do", "ambiente. Os feixes que lança quando", "fica de quatro são tremendamente", "poderosos."],
    "sPokedexText_HYDRAPPLE": ["Estas serpentes caprichosas se uniram.", "Nas raras ocasiões em que seus humores", "se alinham, seu verdadeiro poder", "é liberado."],
    "sPokedexText_GOUGING_FIRE": ["Há pouquíssimos relatos de", "avistamento desta criatura. Um vídeo", "curto a mostra em fúria, jorrando", "pilares de chamas."],
    "sPokedexText_RAGING_BOLT": ["Lembra um Pokemon que virou assunto", "por um tempo depois que uma revista", "paranormal o apontou como ancestral", "de Raikou."],
    "sPokedexText_IRON_BOULDER": ["Foi batizado em referência a um objeto", "misterioso registrado num livro", "antigo. Seu corpo parece ser", "metálico."],
    "sPokedexText_IRON_CROWN": ["Lembra um objeto misterioso", "apresentado numa revista paranormal", "como uma arma de ponta com a forma", "de Cobalion."],
    "sPokedexText_TERAPAGOS": ["Terapagos se protege com seu poder de", "transformar energia em cristais duros.", "Este Pokemon é a fonte do fenômeno", "Terastal."],
    "sPokedexText_PECHARUNT": ["Alimenta os outros com mochis tóxicos", "que despertam desejos e capacidades.", "Quem os come cai sob o controle de", "Pecharunt."],
}
